from qiskit import QuantumCircuit

def solve():
    qc = QuantumCircuit(7)
    layout = {i: i for i in range(5)}
    inv_layout = {i: i for i in range(5)}
    inv_layout[5] = None
    inv_layout[6] = None

    def do_swap(p, q):
        qc.swap(p, q)
        lp = inv_layout[p]
        lq = inv_layout[q]
        inv_layout[p], inv_layout[q] = lq, lp
        if lp is not None:
            layout[lp] = q
        if lq is not None:
            layout[lq] = p

    def route_cx(log_ctrl, log_targ):
        ic = layout[log_ctrl]
        it = layout[log_targ]
        if abs(ic - it) == 1:
            qc.cx(ic, it)
        else:
            if ic < it:
                for k in range(ic, it - 1):
                    do_swap(k, k + 1)
            else:
                for k in range(ic, it + 1, -1):
                    do_swap(k, k - 1)
            qc.cx(layout[log_ctrl], layout[log_targ])

    def apply_rz(log_qubit, angle):
        qc.rz(angle, layout[log_qubit])

    route_cx(0, 4)
    apply_rz(3, 1.735827999833344)
    route_cx(3, 4)
    route_cx(4, 2)
    route_cx(0, 3)
    route_cx(0, 1)
    apply_rz(3, 5.727811035769594)
    route_cx(2, 1)
    route_cx(4, 0)
    route_cx(4, 3)
    apply_rz(3, 0.23231044554829244)

    return qc

