from qiskit.quantum_info import Pauli, Operator, Statevector

def solve():
    pauli_strings = ['YIX', 'IZI', 'IZX', 'IXZ', 'XII', 'XIZ']
    coeffs = np.array([0.519877, -0.120012, 1.497830, -0.814065, -0.294305, -1.363248])
    ops = [Operator(Pauli(ps)) for ps in pauli_strings]

    def energy(theta):
        qc = QuantumCircuit(3)
        for i in range(3):
            qc.ry(theta[i], i)
        qc.cx(0, 1)
        qc.cx(1, 2)
        for i in range(3):
            qc.ry(theta[i+3], i)
        state = Statevector.from_instruction(qc)
        e = 0
        for c, op in zip(coeffs, ops):
            e += c * state.expectation_value(op)
        return np.real(e)

    np.random.seed(42)
    best = 1e9
    for _ in range(5):
        x0 = np.random.rand(6) * 2 * np.pi
        res = minimize(energy, x0, method='COBYLA', options={'maxiter': 200})
        if res.fun < best:
            best = res.fun
    return float(best)

