def solve():
    paulis = ['ZXYI','XZYZ','YZIZ','XXZY','XZIZ','YYZY','ZXII','XYZY']
    coeffs = np.array([-0.514446, -0.528649, 0.914676, -0.334168, -0.979045, 0.225206, 0.353006, -0.343815])
    paulis_q = [p[::-1] for p in paulis]
    H = SparsePauliOp(paulis_q, coeffs)
    H_mat = H.to_matrix()

    def ansatz(theta):
        qc = QuantumCircuit(4)
        for i in range(4):
            qc.ry(theta[i], i)
        for i in range(3):
            qc.cx(i, i+1)
        for i in range(4):
            qc.ry(theta[4+i], i)
        return Statevector(qc)

    def energy(theta):
        psi = ansatz(theta)
        v = psi.data
        return np.real(v.conj() @ (H_mat @ v))

    init = np.random.RandomState(42).uniform(0, np.pi, 8)
    res = minimize(energy, init, method='COBYLA', options={'maxiter':2000})
    return float(res.fun)

