import numpy as np
from qiskit.qasm2 import loads
from qiskit.quantum_info import Operator

def solve():
    qasmA = """
    OPENQASM 2.0;
    include "qelib1.inc";
    qreg q[4];
    t q[1];
    s q[1];
    cz q[2],q[3];
    s q[1];
    s q[2];
    cz q[3],q[0];
    rz(4.124196450638081) q[3];
    rz(5.565039855165545) q[0];
    s q[0];
    cx q[0],q[1];
    """
    qasmB = """
    OPENQASM 2.0;
    include "qelib1.inc";
    qreg q[4];
    t q[1];
    s q[1];
    cz q[2],q[3];
    s q[1];
    s q[2];
    cz q[3],q[0];
    rz(4.124196450638081) q[3];
    rz(6.15661964562299) q[0];
    s q[0];
    cx q[0],q[1];
    """
    qcA = loads(qasmA)
    qcB = loads(qasmB)
    U1 = Operator(qcA).data
    U2 = Operator(qcB).data
    U = np.conj(U1).T @ U2
    d = U.shape[0]
    phi = np.trace(U) / d
    return bool(np.allclose(U, phi * np.eye(d), atol=1e-8))

