import numpy as np

def eq_up_to_global_phase(U1, U2, tol=1e-8):
    flat1 = U1.ravel()
    flat2 = U2.ravel()
    idx = None
    for i, (a, b) in enumerate(zip(flat1, flat2)):
        if abs(a) > tol and abs(b) > tol:
            idx = i
            break
    if idx is None:
        return np.allclose(U1, U2, atol=tol)
    phi = flat1[idx] / flat2[idx]
    phi = phi / abs(phi)
    return np.allclose(U1, phi * U2, atol=tol)

