        if p0 != 'I' and p1 != 'I':
            # local diagonalization
            for p, q in [(p0, q0), (p1, q1)]:
                if p == 'X':
                    circ.h(q)
                elif p == 'Y':
                    circ.sdg(q); circ.h(q)
            # RZZ with angle 2*theta: exp(-i theta Z⊗Z)
            phi = 2 * theta
            circ.cx(q0, q1)
            circ.rz(phi, q1)
            circ.cx(q0, q1)
            # inverse local
            for p, q in [(p1, q1), (p0, q0)]:
                if p == 'X':
                    circ.h(q)
                elif p == 'Y':
                    circ.h(q); circ.s(q)
        else:
            # single-qubit term
            if p0 != 'I':
                p, q = p0, q0
            else:
                p, q = p1, q1
            if p == 'X':
                circ.h(q)
            elif p == 'Y':
                circ.sdg(q); circ.h(q)
            circ.rz(2 * theta, q)
            if p == 'X':
                circ.h(q)
            elif p == 'Y':
                circ.h(q); circ.s(q)
    for _ in range(n):
        for pauli, coeff in terms:
            evolve_pauli(pauli, coeff)
    return circ

