from qiskit import QuantumCircuit

def solve():
    terms = [
        (0.2257, "ZXZ"),
        (0.1715, "ZYX"),
        (1.7214, "IYZ"),
        (-0.8902, "ZYZ"),
        (1.4067, "XIX")
    ]
    n_qubits = 3
    qc = QuantumCircuit(n_qubits)
    t = 1.0
    nsteps = 20
    dt = t / nsteps

    def evolve_term(coeff, pauli, angle):
        # basis change to Z
        for i, p in enumerate(pauli):
            if p == "X":
                qc.h(i)
            elif p == "Y":
                qc.rx(np.pi/2, i)
        # entangle support onto last non-I qubit
        inds = [i for i, p in enumerate(pauli) if p != "I"]
        if inds:
            tgt = inds[-1]
            for ctrl in inds[:-1]:
                qc.cx(ctrl, tgt)
            qc.rz(2 * coeff * angle, tgt)
            for ctrl in reversed(inds[:-1]):
                qc.cx(ctrl, tgt)
        # invert basis change
        for i, p in enumerate(pauli):
            if p == "X":
                qc.h(i)
            elif p == "Y":
                qc.rx(-np.pi/2, i)

    for _ in range(nsteps):
        # forward half-step
        for coeff, pauli in terms:
            evolve_term(coeff, pauli, dt/2)
        # backward half-step
        for coeff, pauli in reversed(terms):
            evolve_term(coeff, pauli, dt/2)

    return qc

