def pauli_exp(circ, coeff, pstr, dt):
    phi = 2 * coeff * dt
    active = [i for i, p in enumerate(pstr) if p != 'I']
    if len(active) == 1:
        i = active[0]
        p = pstr[i]
        if p == 'X':
            circ.rx(phi, i)
        elif p == 'Y':
            circ.ry(phi, i)
        elif p == 'Z':
            circ.rz(phi, i)
    else:
        for i in active:
            p = pstr[i]
            if p == 'X':
                circ.h(i)
            elif p == 'Y':
                circ.rx(np.pi/2, i)
        target = active[-1]
        controls = active[:-1]
        for ctrl in controls:
            circ.cx(ctrl, target)
        circ.rz(phi, target)
        for ctrl in reversed(controls):
            circ.cx(ctrl, target)
        for i in reversed(active):
            p = pstr[i]
            if p == 'X':
                circ.h(i)
            elif p == 'Y':
                circ.rx(-np.pi/2, i)

