import numpy as np

def solve():
    # Define Pauli and gate matrices
    X = np.array([[0, 1], [1, 0]], dtype=complex)
    Y = np.array([[0, -1j], [1j, 0]], dtype=complex)
    Z = np.array([[1, 0], [0, -1]], dtype=complex)
    H = np.array([[1, 1], [1, -1]], dtype=complex) / np.sqrt(2)

    def RZ(theta):
        return np.array([[np.exp(-1j * theta / 2), 0], [0, np.exp(1j * theta / 2)]], dtype=complex)

    I = np.eye(2, dtype=complex)

    def full_op(single, target):
        # 2-qubit system, qubit 0 is least significant (rightmost)
        if target == 0:
            return np.kron(I, single)
        else:
            return np.kron(single, I)

    # Initial density matrix |00><00|
    psi0 = np.zeros(4, dtype=complex)
    psi0[0] = 1
    rho = np.outer(psi0, psi0.conj())

    # Sequence of gates
    theta = 4.223213
    gates = [
        ("h", 0, None),
        ("y", 0, None),
        ("x", 0, None),
        ("rz", 1, theta)
    ]

    p1 = 0.01
    paulis = [X, Y, Z]

    for name, qb, param in gates:
        if name == "h":
            U1 = H
        elif name == "x":
            U1 = X
        elif name == "y":
            U1 = Y
        elif name == "z":
            U1 = Z
        elif name == "rz":
            U1 = RZ(param)
        else:
            raise ValueError("Unknown gate")
        U = full_op(U1, qb)
        # Apply gate
        rho = U @ rho @ U.conj().T
        # Apply depolarizing noise on that qubit
        noisy = (1 - p1) * rho
        for P in paulis:
            Pfull = full_op(P, qb)
            noisy += (p1 / 3) * (Pfull @ rho @ Pfull.conj().T)
        rho = noisy

    # Compute ideal state vector
    # Build total unitary
    U_total = np.eye(4, dtype=complex)
    for name, qb, param in gates:
        if name == "h":
            U1 = H
        elif name == "x":
            U1 = X
        elif name == "y":
            U1 = Y
        elif name == "z":
            U1 = Z
        elif name == "rz":
            U1 = RZ(param)
        U_full = full_op(U1, qb)
        U_total = U_full @ U_total

    psi_ideal = U_total @ psi0
    # Density matrix fidelity
    fid = np.real(psi_ideal.conj().T @ (rho @ psi_ideal))
    return float(fid)

