import numpy as np

def solve():
    n = 3
    I2 = np.eye(2, dtype=complex)
    X = np.array([[0,1],[1,0]], dtype=complex)
    Y = np.array([[0,-1j],[1j,0]], dtype=complex)
    Z = np.array([[1,0],[0,-1]], dtype=complex)
    H = (1/np.sqrt(2)) * np.array([[1,1],[1,-1]], dtype=complex)
    S = np.array([[1,0],[0,1j]], dtype=complex)
    T = np.array([[1,0],[0,np.exp(1j*np.pi/4)]], dtype=complex)
    def Rz(theta):
        return np.array([[np.exp(-1j*theta/2),0],[0,np.exp(1j*theta/2)]], dtype=complex)
    def Ry(theta):
        return np.array([[np.cos(theta/2), -np.sin(theta/2)],
                         [np.sin(theta/2),  np.cos(theta/2)]], dtype=complex)
    # build CNOT on qubits ctrl=0 (lsb), tgt=2 (msb)
    cnot = np.zeros((2**n,2**n), dtype=complex)
    for i in range(2**n):
        b = [(i>>j)&1 for j in range(n)]
        if b[0] == 1:
            b2 = b.copy()
            b2[2] ^= 1
            j = b2[0] + (b2[1]<<1) + (b2[2]<<2)
        else:
            j = i
        cnot[j,i] = 1
    def expand_single(g, target):
        ops = []
        for qu in reversed(range(n)):
            ops.append(g if qu==target else I2)
        M = ops[0]
        for Xx in ops[1:]:
            M = np.kron(M, Xx)
        return M
    def depolarize1(rho, p, target):
        term = np.zeros_like(rho)
        for P in (X, Y, Z):
            Pfull = expand_single(P, target)
            term += Pfull @ rho @ Pfull
        return (1-p)*rho + (p/3)*term
    def depolarize2(rho, p, targets):
        term = np.zeros_like(rho)
        k1, k2 = targets
        for P1 in (I2, X, Y, Z):
            for P2 in (I2, X, Y, Z):
                if P1 is I2 and P2 is I2:
                    continue
                ops = []
                for qu in reversed(range(n)):
                    if qu==k1:
                        ops.append(P1)
                    elif qu==k2:
                        ops.append(P2)
                    else:
                        ops.append(I2)
                Pfull = ops[0]
                for Xx in ops[1:]:
                    Pfull = np.kron(Pfull, Xx)
                term += Pfull @ rho @ Pfull
        return (1-p)*rho + (p/15)*term
    # initial
    psi0 = np.zeros(2**n, dtype=complex)
    psi0[0] = 1
    psi_ideal = psi0.copy()
    rho = np.outer(psi0, psi0.conj())
    # gate sequence
    for gate in [
        ('cx', [0,2], None),
        ('t', [2], None),
        ('y', [0], None),
        ('s', [0], None),
        ('cx', [0,2], None),
        ('h', [1], None),
        ('rz', [2], 1.045059),
        ('ry', [0], 3.592956),
    ]:
        name, qubits, param = gate
        if name == 'cx':
            U = cnot
        elif name == 'h':
            U = expand_single(H, qubits[0])
        elif name == 'x':
            U = expand_single(X, qubits[0])
        elif name == 'y':
            U = expand_single(Y, qubits[0])
        elif name == 'z':
            U = expand_single(Z, qubits[0])
        elif name == 's':
            U = expand_single(S, qubits[0])
        elif name == 't':
            U = expand_single(T, qubits[0])
        elif name == 'rz':
            U = expand_single(Rz(param), qubits[0])
        elif name == 'ry':
            U = expand_single(Ry(param), qubits[0])
        else:
            raise ValueError()
        # ideal state update
        psi_ideal = U @ psi_ideal
        # noisy density update
        rho = U @ rho @ U.conj().T
        # apply depolarizing
        if name == 'cx':
            rho = depolarize2(rho, 0.02, qubits)
        else:
            rho = depolarize1(rho, 0.005, qubits[0])
    fid = np.vdot(psi_ideal, rho @ psi_ideal).real
    return float(fid)

