        ('y', None, 2), ('y', None, 1), ('y', None, 3), ('s', None, 1),
        ('rx', 5.354935, 2), ('s', None, 0), ('rx', 2.171684, 0), ('y', None, 3),
        ('s', None, 4), ('h', None, 0), ('rx', 1.356998, 4), ('t', None, 4),
        ('cx', None, (4,0)), ('rx', 6.103324, 0)
    ]

    # Initialize ideal state and density matrix
    dim = 2**5
    psi = np.zeros((dim,), dtype=complex)
    psi[0] = 1.0
    rho = np.outer(psi, psi.conj())

    # Noise probabilities
    p1 = 0.001
    p2 = 0.008

    # Apply gates
    for gate in seq:
        name, param, qb = gate
        if name == 'rx':
            U = expand_1q(Rx(param), qb)
        elif name == 'ry':
            U = expand_1q(Ry(param), qb)
        elif name == 'rz':
            U = expand_1q(Rz(param), qb)
        elif name == 'h':
            U = expand_1q(H, qb)
        elif name == 'x':
            U = expand_1q(X, qb)
        elif name == 'y':
            U = expand_1q(Y, qb)
        elif name == 'z':
            U = expand_1q(Z, qb)
        elif name == 's':
            U = expand_1q(S, qb)
        elif name == 't':
            U = expand_1q(T, qb)
        elif name == 'cx':
            c, t = qb
            U = expand_cnot(c, t)
        else:
            raise ValueError("Unknown gate")
        # Ideal state update
        psi = U.dot(psi)
        # Density matrix unitary update
        rho = U.dot(rho).dot(U.conj().T)
        # Noise
        if name == 'cx':
            c, t = qb
            ops = noise_ops_2q[(c, t)]
            tot = np.zeros_like(rho)
            for P in ops:
                tot += P.dot(rho).dot(P)
            rho = (1-p2)*rho + (p2/15)*tot
        else:
            ops = noise_ops_1q[qb]
            tot = sum(P.dot(rho).dot(P) for P in ops)
            rho = (1-p1)*rho + (p1/3)*tot

    # Fidelity
    fid = np.vdot(psi, rho.dot(psi))
    return float(fid.real)

