    if kind == "x":
        qc.x(qubits[0])
    elif kind == "y":
        qc.y(qubits[0])
    elif kind == "z":
        qc.z(qubits[0])
    elif kind == "h":
        qc.h(qubits[0])
    elif kind == "s":
        qc.s(qubits[0])
    elif kind == "t":
        qc.t(qubits[0])
    elif kind == "cx":
        qc.cx(qubits[0], qubits[1])
    elif kind == "cz":
