from qiskit import QuantumCircuit
from qiskit.qasm2 import loads
import numpy as np
from qiskit.quantum_info import Statevector, DensityMatrix, Pauli

def solve():
    qasm = """OPENQASM 2.0;
include "qelib1.inc";
qreg q[4];
x q[0];
cz q[3],q[0];
ry(2.488215421766685) q[3];
cz q[2],q[3];
t q[0];
h q[0];
h q[1];
s q[2];
y q[1];
t q[3];
y q[3];
rz(4.994394377350793) q[2];
cx q[3],q[1];
t q[3];
ry(3.9497983066763553) q[2];
cz q[1],q[3];
h q[2];
rx(2.0026062018409263) q[3];
cz q[2],q[1];
cz q[2],q[0];
cz q[2],q[0];
ry(2.922629114558955) q[0];
y q[1];
cz q[1],q[3];
cx q[1],q[2];
h q[2];
"""
    qc = loads(qasm)

    expected = {
        "1000": 0.1944, "1110": 0.1944, "1001": 0.1250, "1111": 0.1250,
        "0000": 0.0974, "0110": 0.0974, "0001": 0.0626, "0111": 0.0626,
        "1100": 0.0083, "1010": 0.0083, "1101": 0.0054, "1011": 0.0054,
        "0010": 0.0042, "0100": 0.0042, "0011": 0.0027, "0101": 0.0027,
    }
    observed = {
        "1000": 0.1281, "1110": 0.1281, "1001": 0.0903, "1111": 0.0903,
        "0000": 0.0802, "0110": 0.0802, "0001": 0.0571, "0111": 0.0571,
        "1100": 0.0500, "1010": 0.0500, "1101": 0.0368, "1011": 0.0368,
        "0010": 0.0331, "0100": 0.0331, "0011": 0.0245, "0101": 0.0245,
    }

    pauli_1q = [Pauli("I"), Pauli("X"), Pauli("Y"), Pauli("Z")]
    pauli_2q_labels = []
    for a in "IXYZ":
        for b in "IXYZ":
            if a + b != "II":
                pauli_2q_labels.append(a + b)
    pauli_2q = [Pauli(lbl) for lbl in pauli_2q_labels]

    def apply_1q_depol(rho, p, qidx, n=4):
        out = (1 - p) * rho.data.copy()
        for lbl in ["X", "Y", "Z"]:
            full = ["I"] * n
            full[n - 1 - qidx] = lbl
            P = Pauli("".join(full)).to_matrix()
            out += (p / 3.0) * (P @ rho.data @ P.conj().T)
        return DensityMatrix(out)

    def apply_2q_depol(rho, p, q0, q1, n=4):
        out = (1 - p) * rho.data.copy()
        for lbl in pauli_2q_labels:
            full = ["I"] * n
            full[n - 1 - q0] = lbl[0]
            full[n - 1 - q1] = lbl[1]
            P = Pauli("".join(full)).to_matrix()
            out += (p / 15.0) * (P @ rho.data @ P.conj().T)
        return DensityMatrix(out)

    def noisy_probs(circuit):
        rho = DensityMatrix(Statevector.from_label("0000"))
        for inst, qargs, _ in circuit.data:
            name = inst.name
            qubits = [circuit.find_bit(q).index for q in qargs]
            if name == "barrier":
                continue
            if name in {"x", "y", "z", "h", "s", "sdg", "t", "tdg", "rx", "ry", "rz"}:
                op = QuantumCircuit(4)
                getattr(op, name)(*(list(inst.params) + [qubits[0]]) if name in {"rx", "ry", "rz"} else [qubits[0]])
                U = Statevector.from_instruction(op).evolve(QuantumCircuit(4)).dims()
            op_full = QuantumCircuit(4)
            if name in {"x", "y", "z", "h", "s", "sdg", "t", "tdg"}:
                getattr(op_full, name)(qubits[0])
            elif name in {"rx", "ry", "rz"}:
                getattr(op_full, name)(float(inst.params[0]), qubits[0])
            elif name in {"cx", "cz"}:
                getattr(op_full, name)(qubits[0], qubits[1])
            else:
                raise ValueError(name)
            U = Statevector.from_instruction(op_full).to_operator().data
            rho = DensityMatrix(U @ rho.data @ U.conj().T)
            if len(qubits) == 1:
                rho = apply_1q_depol(rho, 0.02, qubits[0], 4)
            else:
                rho = apply_2q_depol(rho, 0.05, qubits[0], qubits[1], 4)
        probs = {}
        diag = np.real(np.diag(rho.data))
        for i, p in enumerate(diag):
            probs[format(i, "04b")] = float(p)
        return probs

    probs = noisy_probs(qc)

    def tvd(d1, d2):
        keys = set(d1) | set(d2)
        return 0.5 * sum(abs(d1.get(k, 0.0) - d2.get(k, 0.0)) for k in keys)

    tvd_obs_sim = tvd(observed, probs)
    tvd_exp_sim = tvd(expected, probs)

    if tvd_obs_sim < 0.08:
        return qc
    return qc

