import numpy as np
from scipy.optimize import minimize
from qiskit import QuantumCircuit
from qiskit.quantum_info import Statevector, SparsePauliOp

def _build_hamiltonian():
    terms = [
        ("IZIZ", -1.007755),
        ("YIIX",  1.404643),
        ("IIZX", -0.145175),
        ("XZZY",  0.992688),
        ("IXIY",  1.420416),
        ("YZZX",  0.715544),
        ("XYIX", -1.103182),
        ("ZZZY",  0.258612),
    ]
    paulis = [p for p, _ in terms]
    coeffs = [c for _, c in terms]
    return SparsePauliOp(paulis, coeffs=coeffs)

def _ansatz(params, n=4, layers=3):
    qc = QuantumCircuit(n)
    k = 0
    for q in range(n):
        qc.ry(params[k], q); k += 1
        qc.rz(params[k], q); k += 1
    for _ in range(layers):
        for q in range(n - 1):
            qc.cx(q, q + 1)
        qc.cx(n - 1, 0)
        for q in range(n):
            qc.ry(params[k], q); k += 1
            qc.rz(params[k], q); k += 1
    return qc

def _energy(params, hamiltonian, n=4, layers=3):
    qc = _ansatz(params, n=n, layers=layers)
    sv = Statevector.from_instruction(qc)
    return float(np.real(sv.expectation_value(hamiltonian)))

def solve():
    np.random.seed(7)
    hamiltonian = _build_hamiltonian()
    n = 4
    layers = 3
    num_params = 2 * n * (layers + 1)

    best_val = float("inf")
    best_x = None

    initials = [np.zeros(num_params)]
    for _ in range(12):
        initials.append(np.random.uniform(-np.pi, np.pi, size=num_params))

    for x0 in initials:
        res = minimize(
            _energy,
            x0,
            args=(hamiltonian, n, layers),
            method="COBYLA",
            options={"maxiter": 2000, "rhobeg": 0.5, "tol": 1e-7}
        )
        if res.fun < best_val:
            best_val = float(res.fun)
            best_x = res.x

    for method in ["Powell", "Nelder-Mead"]:
        res = minimize(
            _energy,
            best_x,
            args=(hamiltonian, n, layers),
            method=method,
            options={"maxiter": 3000, "xtol": 1e-8, "ftol": 1e-8} if method == "Powell" else {"maxiter": 3000, "xatol": 1e-8, "fatol": 1e-8}
        )
        if res.fun < best_val:
            best_val = float(res.fun)
            best_x = res.x

    return float(best_val)

if __name__ == "__main__":
    print(solve())

