        out = np.kron(out, m)
    return out

def _basis_change_in(qc, q, p):
    if p == 'X':
        qc.h(q)
    elif p == 'Y':
        qc.rx(np.pi / 2, q)

def _basis_change_out(qc, q, p):
    if p == 'X':
        qc.h(q)
    elif p == 'Y':
        qc.rx(-np.pi / 2, q)

def _append_pauli_evolution(qc, pauli, coeff, dt):
    active = [i for i, ch in enumerate(pauli) if ch != 'I']
    if not active:
        return
    for q in active:
        _basis_change_in(qc, q, pauli[q])
    for a, b in zip(active[:-1], active[1:]):
        qc.cx(a, b)
    qc.rz(2.0 * coeff * dt, active[-1])
    for a, b in zip(reversed(active[:-1]), reversed(active[1:])):
        qc.cx(a, b)
    for q in active:
        _basis_change_out(qc, q, pauli[q])

def _build_trotter_circuit(nsteps, t):
    terms = [
        (0.9718, "XYZYY"),
        (0.1145, "IZIZI"),
        (1.7862, "IZZYX"),
        (-0.4821, "XXZZY"),
        (-1.3238, "YZZYZ"),
        (-1.8761, "IYIIY"),
        (1.9121, "IYIIZ"),
        (0.6688, "YXIIZ"),
        (0.4858, "IXXZI"),
        (1.1280, "IIIIX"),
        (0.6082, "YYYZY"),
        (-1.7962, "ZZZXX"),
    ]
    qc = QuantumCircuit(5)
    dt = t / nsteps
    for _ in range(nsteps):
        for coeff, pauli in terms:
            _append_pauli_evolution(qc, pauli, coeff, dt)
    return qc

def _exact_unitary(t):
    terms = [
        (0.9718, "XYZYY"),
        (0.1145, "IZIZI"),
        (1.7862, "IZZYX"),
        (-0.4821, "XXZZY"),
        (-1.3238, "YZZYZ"),
        (-1.8761, "IYIIY"),
        (1.9121, "IYIIZ"),
        (0.6688, "YXIIZ"),
        (0.4858, "IXXZI"),
        (1.1280, "IIIIX"),
        (0.6082, "YYYZY"),
        (-1.7962, "ZZZXX"),
    ]
    H = np.zeros((32, 32), dtype=complex)
    for coeff, pauli in terms:
        H += coeff * _pauli_string_matrix(pauli)
    return expm(-1j * H * t)

def _operator_fidelity(U, V):
    d = U.shape[0]
    return abs(np.trace(np.conjugate(U.T) @ V)) / d

def solve():
    t = 1.5
    exact = _exact_unitary(t)
    best_qc = None
    best_fid = -1.0
    for nsteps in range(1, 13):
        qc = _build_trotter_circuit(nsteps, t)
        approx = Operator(qc).data
        fid = _operator_fidelity(exact, approx)
        if fid > best_fid:
            best_fid = fid
            best_qc = qc
        if fid > 0.99:
            return qc
    return best_qc

