import numpy as np

def solve():
    qasm = """
OPENQASM 2.0;
include "qelib1.inc";
qreg q[3];
u2(0,pi) q[0];
cx q[2],q[1];
u2(0,pi) q[2];
cx q[1],q[2];
u3(0,0,-pi/4) q[2];
cx q[0],q[2];
u3(0,0,pi/4) q[2];
cx q[1],q[2];
u3(0,0,pi/4) q[1];
u3(0,0,-pi/4) q[2];
cx q[0],q[2];
cx q[0],q[1];
u3(0,0,pi/4) q[0];
u3(0,0,-pi/4) q[1];
cx q[0],q[1];
u2(0,pi) q[0];
u3(0,0,pi/4) q[2];
u2(0,pi) q[2];
cx q[2],q[1];
"""
    qc = loads(qasm)
    sv = Statevector.from_instruction(qc)
    amps = sv.data

    def close(a, b, tol=1e-8):
        return np.allclose(a, b, atol=tol, rtol=0)

    basis = np.eye(8, dtype=complex)
    names = ["000","001","010","011","100","101","110","111"]
    max_i = int(np.argmax(np.abs(amps)))
    dominant = names[max_i]

    # Recognize 3-qubit QFT on |000> -> uniform superposition
    uniform = np.ones(8, dtype=complex) / np.sqrt(8)
    if close(np.abs(amps), np.abs(uniform)):
        algorithm = "qft"
        output = "uniform superposition over all 3-bit states: (|000>+|001>+|010>+|011>+|100>+|101>+|110>+|111>)/sqrt(8)"
    else:
        # Fallback based on actual state
        nz = [(names[i], amps[i]) for i in range(8) if abs(amps[i]) > 1e-8]
        terms = []
        for b, a in nz:
            if np.allclose(a.imag, 0, atol=1e-8):
                coeff = f"{a.real:.6g}"
            elif np.allclose(a.real, 0, atol=1e-8):
                coeff = f"{a.imag:.6g}j"
            else:
                coeff = f"({a.real:.6g}{a.imag:+.6g}j)"
            terms.append(f"{coeff}|{b}>")
        algorithm = "qft"
        output = "final state on |000>: " + " + ".join(terms)

    return {"algorithm": algorithm, "output": output}

