import numpy as np
from qiskit import QuantumCircuit
from qiskit.quantum_info import Operator
from scipy.linalg import expm

def _pauli_matrix(p):
    if p == 'I':
        return np.array([[1, 0], [0, 1]], dtype=complex)
    if p == 'X':
        return np.array([[0, 1], [1, 0]], dtype=complex)
    if p == 'Y':
        return np.array([[0, -1j], [1j, 0]], dtype=complex)
    if p == 'Z':
        return np.array([[1, 0], [0, -1]], dtype=complex)
    raise ValueError(p)

def _pauli_string_matrix(ps):
    mats = [_pauli_matrix(c) for c in ps]
    out = mats[0]
    for m in mats[1:]:
        out = np.kron(out, m)
    return out

def _apply_basis_change(qc, qubit, p):
    if p == 'X':
        qc.h(qubit)
    elif p == 'Y':
        qc.rx(np.pi / 2, qubit)

def _undo_basis_change(qc, qubit, p):
    if p == 'X':
        qc.h(qubit)
    elif p == 'Y':
        qc.rx(-np.pi / 2, qubit)

def _append_pauli_evolution(qc, coeff, pauli, dt):
    active = [i for i, p in enumerate(pauli) if p != 'I']
    if not active:
        return
    for q in active:
        _apply_basis_change(qc, q, pauli[q])
    pivot = active[-1]
    for q in active[:-1]:
        qc.cx(q, pivot)
    qc.rz(2.0 * coeff * dt, pivot)
    for q in reversed(active[:-1]):
        qc.cx(q, pivot)
    for q in active:
        _undo_basis_change(qc, q, pauli[q])

def _build_trotter_circuit(terms, t, steps):
    qc = QuantumCircuit(5)
    dt = t / steps
    for _ in range(steps):
        for coeff, pauli in terms:
            _append_pauli_evolution(qc, coeff, pauli, dt / 2.0)
        for coeff, pauli in reversed(terms):
            _append_pauli_evolution(qc, coeff, pauli, dt / 2.0)
    return qc

def _operator_fidelity(U, V):
    d = U.shape[0]
    return abs(np.trace(np.conjugate(U.T) @ V)) / d

def solve():
    t = 1.5
    terms = [
        (1.8411, "IZIZX"),
        (0.0353, "IYIIX"),
        (0.3953, "IZIIZ"),
        (0.9101, "XZXXZ"),
        (0.4953, "ZYYZI"),
        (-0.2601, "XIYXZ"),
        (-0.7357, "YZZXY"),
        (-0.9034, "YXYIX"),
        (0.9686, "IIZZZ"),
        (0.5952, "YIYYX"),
        (-1.0141, "XZYZY"),
        (0.5506, "XXXII"),
    ]

    H = np.zeros((32, 32), dtype=complex)
    for coeff, pauli in terms:
        H += coeff * _pauli_string_matrix(pauli)
    U_exact = expm(-1j * t * H)

    best_qc = None
    best_fid = -1.0
    for steps in range(1, 21):
        qc = _build_trotter_circuit(terms, t, steps)
        U_trot = Operator(qc).data
        fid = _operator_fidelity(U_exact, U_trot)
        if fid > best_fid:
            best_fid = fid
            best_qc = qc
        if fid > 0.99:
            return qc
    return best_qc

