from qiskit import QuantumCircuit
from qiskit.quantum_info import Operator, Statevector
import numpy as np
from scipy.linalg import expm

def pauli_matrix(pauli_char):
    if pauli_char == 'I':
        return np.eye(2, dtype=complex)
    elif pauli_char == 'X':
        return np.array([[0,1],[1,0]], dtype=complex)
    elif pauli_char == 'Y':
        return np.array([[0,-1j],[1j,0]], dtype=complex)
    elif pauli_char == 'Z':
        return np.array([[1,0],[0,-1]], dtype=complex)
    else:
        raise ValueError("Invalid Pauli character")

def pauli_string_to_matrix(pauli_str):
    # pauli_str length 3 for 3 qubits
    mat = pauli_matrix(pauli_str[0])
    for c in pauli_str[1:]:
        mat = np.kron(mat, pauli_matrix(c))
    return mat

def single_qubit_exp(pauli, theta, qubit, circ):
    # Implement exp(-i theta/2 * P) for single qubit P in {X,Y,Z}
    # Using standard gates rx, ry, rz, cx, h
    # Note: exp(-i theta/2 * P) = R_P(theta)
    # We implement R_P(theta) = exp(-i theta/2 P)
    # Qiskit rx(theta) = exp(-i theta/2 X)
    # ry(theta) = exp(-i theta/2 Y)
    # rz(theta) = exp(-i theta/2 Z)
    if pauli == 'X':
        circ.rx(theta, qubit)
    elif pauli == 'Y':
        circ.ry(theta, qubit)
    elif pauli == 'Z':
        circ.rz(theta, qubit)
    else:
        raise ValueError("Invalid single qubit Pauli for rotation")

def two_qubit_exp(pauli1, qubit1, pauli2, qubit2, theta, circ):
    # Implement exp(-i theta/2 * P1 P2) for two qubits
    # P1,P2 in {X,Y,Z}
    # Use standard decomposition:
    # 1) Change basis so that P1 and P2 become Z
    # 2) Apply CNOT chain
    # 3) Rz rotation on target qubit
    # 4) Undo CNOT chain
    # 5) Undo basis change

    def basis_change(p, q):
        # Change basis so that p -> Z on qubit q
        if p == 'X':
            circ.h(q)
        elif p == 'Y':
            circ.rx(np.pi/2, q)
        elif p == 'Z':
            pass
        else:
            raise ValueError("Invalid Pauli for basis change")

    def basis_change_inv(p, q):
        # Inverse basis change
        if p == 'X':
            circ.h(q)
        elif p == 'Y':
            circ.rx(-np.pi/2, q)
        elif p == 'Z':
            pass
        else:
            raise ValueError("Invalid Pauli for basis change")

    basis_change(pauli1, qubit1)
    basis_change(pauli2, qubit2)

    # Apply CNOT qubit1->qubit2
    circ.cx(qubit1, qubit2)
    # Rz rotation on qubit2 by 2*theta (because exp(-i theta/2 Z1 Z2) = CNOT Rz(2 theta) CNOT)
    circ.rz(2*theta, qubit2)
    circ.cx(qubit1, qubit2)

    basis_change_inv(pauli1, qubit1)
    basis_change_inv(pauli2, qubit2)

def three_qubit_exp(pauli_str, theta, circ):
    # Implement exp(-i theta/2 * P0 P1 P2) for 3 qubits
    # P0,P1,P2 in {I,X,Y,Z}
    # We assume no identity in the middle of the string (if identity, reduce to fewer qubits)
    # Strategy:
    # 1) Change basis on each qubit so that P_i -> Z or I
    # 2) Use multi-CNOT chain to reduce to Rz on last qubit
    # 3) Rz rotation by 2*theta on last qubit
    # 4) Undo CNOT chain
    # 5) Undo basis changes

    # Identify qubits with non-identity Pauli
    qubits = [i for i, p in enumerate(pauli_str) if p != 'I']
    if len(qubits) == 0:
        # Identity operator, exp(-i theta/2 * I) = global phase, ignore
        return
    if len(qubits) == 1:
        # Single qubit rotation
        single_qubit_exp(pauli_str[qubits[0]], 2*theta, qubits[0], circ)
        return
    if len(qubits) == 2:
        # Two qubit rotation
        two_qubit_exp(pauli_str[qubits[0]], qubits[0], pauli_str[qubits[1]], qubits[1], theta, circ)
        return

    # For 3 qubits:
    # Basis change
    def basis_change(p, q):
        if p == 'X':
            circ.h(q)
        elif p == 'Y':
            circ.rx(np.pi/2, q)
        elif p == 'Z':
            pass
        elif p == 'I':
            pass
        else:
            raise ValueError("Invalid Pauli for basis change")

    def basis_change_inv(p, q):
        if p == 'X':
            circ.h(q)
        elif p == 'Y':
            circ.rx(-np.pi/2, q)
        elif p == 'Z':
            pass
        elif p == 'I':
            pass
        else:
            raise ValueError("Invalid Pauli for basis change")

    for i in range(3):
        basis_change(pauli_str[i], i)

    # Multi-CNOT chain to parity on last qubit
    # We do CNOT qubit0->qubit2, CNOT qubit1->qubit2
    circ.cx(0,2)
    circ.cx(1,2)

    # Rz rotation on qubit2 by 2*theta
    circ.rz(2*theta, 2)

    # Undo CNOT chain
    circ.cx(1,2)
    circ.cx(0,2)

    for i in range(3):
        basis_change_inv(pauli_str[i], i)

def solve():
    # Hamiltonian terms and coefficients
    terms = [
        (0.8654, "IIY"),
        (1.2474, "ZYX"),
        (0.5024, "YZX"),
        (0.5194, "YYZ"),
        (1.9143, "IXI"),
    ]
    t = 1.0

    # We want operator fidelity > 0.99 with exact exp(-iHt)
    # Use Trotter steps n=5 for good accuracy
    n = 5
    dt = t / n

    circ = QuantumCircuit(3)

    # Build exact operator for fidelity check
    H = np.zeros((8,8), dtype=complex)
    for c, pstr in terms:
        H += c * pauli_string_to_matrix(pstr)
    U_exact = expm(-1j * H * t)

    # Build Trotter circuit operator
    def trotter_step_circuit():
        step_circ = QuantumCircuit(3)
        for c, pstr in terms:
            three_qubit_exp(pstr, -c*dt, step_circ)
        return step_circ

    # Append n Trotter steps
    for _ in range(n):
        circ.compose(trotter_step_circuit(), inplace=True)

    # Check fidelity (optional, not required to return)
    # U_trot = Operator(circ).data
    # fid = np.abs(np.trace(np.dot(U_trot.conj().T, U_exact))) / 8
    # assert fid > 0.99

    return circ

