import numpy as np

def solve():
    qasm_str = """
    OPENQASM 2.0;
    include "qelib1.inc";
    qreg q[4];
    swap q[1],q[2];
    swap q[0],q[3];
    h q[3];
    cp(-pi/2) q[3],q[2];
    h q[2];
    cp(-pi/4) q[3],q[1];
    cp(-pi/2) q[2],q[1];
    h q[1];
    cp(-pi/8) q[3],q[0];
    cp(-pi/4) q[2],q[0];
    cp(-pi/2) q[1],q[0];
    h q[0];
    """
    # Load circuit from QASM
    circuit = loads(qasm_str)

    # The circuit applies swaps to reorder qubits, then applies a sequence of Hadamards and controlled phase gates
    # with angles -pi/2, -pi/4, -pi/8, etc. on qubits in descending order.
    # This pattern matches the Quantum Fourier Transform (QFT) on 4 qubits, but with swaps at the start instead of the end.
    # The QFT circuit typically applies Hadamard on the most significant qubit, then controlled phase rotations on less significant qubits,
    # then proceeds to the next qubit, etc.
    # The swaps reorder the qubits so that the QFT is applied in a different qubit order.
    # Hence, this is the QFT circuit on 4 qubits.

    # Let's verify by simulating the output statevector on |0000>
    sv = Statevector.from_label('0000')
    sv = sv.evolve(circuit)

    # The QFT on |0>^n produces equal superposition with phases all 1/sqrt(2^n)
    # So the output should be uniform superposition over all 16 states with equal amplitudes 1/4 (since 2^4=16)
    # Let's check amplitudes magnitudes
