    if np.allclose(np.abs(amplitudes), uniform_amplitude, atol=1e-8):
        output_desc = "Uniform superposition over all 16 computational basis states with equal amplitudes 1/4"
    else:
        output_desc = "Output state is not uniform superposition"

    return {
        'algorithm': 'qft',
        'output': output_desc
    }

