    u2(0,pi) q[0];
    u2(0,pi) q[1];
    u2(0,pi) q[2];
    u3(pi,0,pi) q[3];
    u2(0,pi) q[3];
    cx q[1],q[3];
    u2(0,pi) q[1];
    cx q[2],q[3];
    u2(0,pi) q[2];
    """
    circuit = loads(qasm_str)

