from qiskit import QuantumCircuit
from qiskit.qasm2 import loads
from qiskit.quantum_info import Statevector
import numpy as np

def solve():
    qasm_str = """
    OPENQASM 2.0;
    include "qelib1.inc";
    qreg q[3];
    u2(0,pi) q[0];
    cx q[2],q[1];
    u2(0,pi) q[2];
    cx q[1],q[2];
    u3(0,0,-pi/4) q[2];
    cx q[0],q[2];
    u3(0,0,pi/4) q[2];
    cx q[1],q[2];
    u3(0,0,pi/4) q[1];
    u3(0,0,-pi/4) q[2];
    cx q[0],q[2];
    cx q[0],q[1];
    u3(0,0,pi/4) q[0];
    u3(0,0,-pi/4) q[1];
    cx q[0],q[1];
    u2(0,pi) q[0];
    u3(0,0,pi/4) q[2];
    u2(0,pi) q[2];
    cx q[2],q[1];
    """
    circuit = loads(qasm_str)

    # Initial state |000>
    init_state = Statevector.from_label('000')
    final_state = init_state.evolve(circuit)

    # The circuit is a known decomposition of the 3-qubit Quantum Fourier Transform (QFT)
    # on 3 qubits. The pattern of Hadamard-like gates (u2(0,pi) ~ H), controlled phase rotations,
    # and swaps is characteristic of QFT.
    #
    # Check if final_state matches the QFT|000> = (|0>+|1>+|2>+...)/sqrt(8)
    # i.e. uniform superposition over computational basis states.
    # The amplitudes should all be 1/sqrt(8) with zero phase.

    # Compute expected amplitudes
    expected_amplitude = 1/np.sqrt(8)
    amplitudes = final_state.data
    uniform = np.allclose(np.abs(amplitudes), expected_amplitude, atol=1e-7)
    phases_zero = np.allclose(np.angle(amplitudes), 0, atol=1e-7) or np.allclose(np.angle(amplitudes), 2*np.pi, atol=1e-7)

    if uniform and phases_zero:
        algorithm = 'qft'
        output = "Uniform superposition of all computational basis states with equal amplitude 1/sqrt(8)"
    else:
        # fallback (not expected)
        algorithm = 'unknown'
        output = "Unknown output state"

    return {'algorithm': algorithm, 'output': output}

