    u2(0,pi) q[2];
    cx q[4],q[5];
    u2(0,pi) q[4];
    """
    circuit = loads(qasm_str)

    # Simplify repeated u2(0,pi) on same qubit:
    # u2(0,pi) = Hadamard (H) gate
    # Two consecutive u2(0,pi) on q[1] and q[3] cancel out (H*H=I)
    # So effectively q[1] and q[3] are unchanged from |0>
    # q[0], q[2], q[4] each get one H gate
    # q[5] gets u3(pi,0,pi) then u2(0,pi)
    # u3(pi,0,pi) = X gate (up to global phase)
    # u2(0,pi) = H
    # So q[5] gets X then H

    # Then controlled-NOTs from q[0], q[2], q[4] to q[5]
    # Then H gates on q[0], q[2], q[4]

    # Let's analyze the state stepwise:
    # Initial: |000000>
    # After H on q[0], q[2], q[4]: these qubits in superposition (|+>)
    # q[1], q[3] remain |0>
    # q[5] after X then H: X|0> = |1>, then H|1> = (|0> - |1>)/sqrt(2) = |-> state

    # Then apply CNOTs with q[0], q[2], q[4] as controls and q[5] as target
    # This flips q[5] if control is 1

    # This is a known pattern for the Grover diffusion operator on 3 qubits (q[0], q[2], q[4]) with ancilla q[5]
    # The ancilla q[5] is prepared in |-> state, then CNOTs controlled by the qubits to be diffused,
    # then Hadamards on those qubits again.
    # This implements the Grover diffusion operator on q[0], q[2], q[4].
    # q[1] and q[3] are untouched and remain |0>.

    # So the circuit implements the Grover diffusion operator on 3 qubits embedded in a 6-qubit register.

