    elif name == 'cz':
        qc.cz(qubits[0], qubits[1])
    elif name == 'swap':
        qc.swap(qubits[0], qubits[1])
    elif name == 'cy':
        qc.cy(qubits[0], qubits[1])
    elif name == 'x':
        qc.x(qubits[0])
    elif name == 'y':
