    elif name == 'h':
        qc.h(qubits[0])
    elif name == 's':
        qc.s(qubits[0])
    elif name == 'sdg':
        qc.sdg(qubits[0])
    elif name == 't':
        qc.t(qubits[0])
    elif name == 'tdg':
        qc.tdg(qubits[0])
    elif name == 'id':
        qc.id(qubits[0])
    else:
        raise ValueError(f"Unknown gate {name}")


def _build_circuit(gates, n=3):
    qc = QuantumCircuit(n)
    for name, qubits in gates:
        _apply(qc, name, qubits)
    return qc


def _target_unitary():
    s2 = 1 / np.sqrt(2)
