    U[5, 5] = s2
    U[2, 6] = -s2
    U[5, 6] = s2
    U[0, 7] = s2
    U[7, 7] = s2
    return U


def _same_unitary(U, V, tol=1e-3):
    M = V @ U.conj().T
    phase = M[0, 0]
    if abs(phase) < 1e-8:
        # try another index
        idxs = np.argwhere(np.abs(M) > 1e-6)
