        ('t', [0], []),
        ('rx', [0], [0.7925685333361148]),
    ]

    single_qubit_fixed = ['x', 'y', 'z', 'h', 's', 'sdg', 't', 'tdg', 'id']
    rotation_names = ['rx', 'ry', 'rz']
    two_qubit_names = ['cx', 'cz', 'swap', 'cy']

    def build_circuit(gates):
        qc = QuantumCircuit(3)
        for name, qubits, params in gates:
            if name == 'x':
                qc.x(qubits[0])
            elif name == 'y':
                qc.y(qubits[0])
            elif name == 'z':
                qc.z(qubits[0])
            elif name == 'h':
                qc.h(qubits[0])
            elif name == 's':
                qc.s(qubits[0])
            elif name == 'sdg':
                qc.sdg(qubits[0])
            elif name == 't':
                qc.t(qubits[0])
            elif name == 'tdg':
                qc.tdg(qubits[0])
            elif name == 'id':
                qc.id(qubits[0])
            elif name == 'rx':
                qc.rx(params[0], qubits[0])
            elif name == 'ry':
                qc.ry(params[0], qubits[0])
            elif name == 'rz':
                qc.rz(params[0], qubits[0])
            elif name == 'cx':
                qc.cx(qubits[0], qubits[1])
            elif name == 'cz':
                qc.cz(qubits[0], qubits[1])
            elif name == 'cy':
                qc.cy(qubits[0], qubits[1])
            elif name == 'swap':
                qc.swap(qubits[0], qubits[1])
        return qc

    def overlap(U1, U2):
        n = U1.shape[0]
        val = np.trace(U1.conj().T @ U2) / n
        return abs(val)

    best_overlap = -1.0
    best_gates = None

    def evaluate(gates):
        nonlocal best_overlap, best_gates
        try:
            qc = build_circuit(gates)
            U = Operator(qc).data
        except Exception:
            return
        ov = overlap(U_target, U)
        if ov > best_overlap:
            best_overlap = ov
            best_gates = gates

    # Baseline
    evaluate(original_gates)

    THRESH = 0.999

    # ---- Stage 1: rename gate at each position ----
    def try_rename():
        nonlocal best_overlap, best_gates
        for i, (name, qubits, params) in enumerate(original_gates):
            if len(qubits) == 1:
                candidates = []
                # fixed -> fixed / rotation(with same param if original had rotation)
                for cand in single_qubit_fixed:
                    if cand != name:
                        candidates.append((cand, qubits, []))
                for cand in rotation_names:
                    if name in rotation_names:
                        # keep same angle, change axis
                        if cand != name:
                            candidates.append((cand, qubits, params))
                for name2, q2, p2 in candidates:
                    new_gates = list(original_gates)
                    new_gates[i] = (name2, q2, p2)
                    evaluate(new_gates)
                    if best_overlap >= THRESH and best_gates == new_gates:
                        return True
            elif len(qubits) == 2:
                for cand in two_qubit_names:
                    if cand != name:
                        new_gates = list(original_gates)
                        new_gates[i] = (cand, qubits, [])
                        evaluate(new_gates)
                        if best_overlap >= THRESH and best_gates == new_gates:
                            return True
        return False

    found = try_rename()

    # ---- Stage 2: qubit variation ----
    if not found and best_overlap < THRESH:
        def try_qubit_change():
            nonlocal best_overlap, best_gates
            for i, (name, qubits, params) in enumerate(original_gates):
                if len(qubits) == 1:
                    orig_q = qubits[0]
                    for q in range(3):
                        if q != orig_q:
                            new_gates = list(original_gates)
                            new_gates[i] = (name, [q], params)
                            evaluate(new_gates)
                            if best_overlap >= THRESH and best_gates == new_gates:
                                return True
                elif len(qubits) == 2:
                    all_pairs = [(a, b) for a in range(3) for b in range(3) if a != b]
                    for pair in all_pairs:
                        if list(pair) != qubits:
                            new_gates = list(original_gates)
                            new_gates[i] = (name, list(pair), [])
                            evaluate(new_gates)
                            if best_overlap >= THRESH and best_gates == new_gates:
                                return True
            return False
        found = try_qubit_change()

    # ---- Stage 3: removal ----
    if not found and best_overlap < THRESH:
        def try_removal():
            nonlocal best_overlap, best_gates
            for i in range(len(original_gates)):
                new_gates = original_gates[:i] + original_gates[i+1:]
                evaluate(new_gates)
                if best_overlap >= THRESH and best_gates == new_gates:
                    return True
            return False
        found = try_removal()

    # ---- Stage 4: insertion of a missing gate ----
    if not found and best_overlap < THRESH:
        def try_insertion():
            nonlocal best_overlap, best_gates
            insert_single = single_qubit_fixed
            insert_two = ['cx', 'cz', 'cy', 'swap']
            for pos in range(len(original_gates) + 1):
                for name in insert_single:
                    for q in range(3):
                        new_gates = original_gates[:pos] + [(name, [q], [])] + original_gates[pos:]
                        evaluate(new_gates)
                        if best_overlap >= THRESH and best_gates == new_gates:
                            return True
                for name in insert_two:
                    for a in range(3):
                        for b in range(3):
                            if a != b:
                                new_gates = original_gates[:pos] + [(name, [a, b], [])] + original_gates[pos:]
                                evaluate(new_gates)
                                if best_overlap >= THRESH and best_gates == new_gates:
                                    return True
            return False
        found = try_insertion()

    # Build final circuit from the best found gate sequence
    final_gates = best_gates if best_gates is not None else original_gates
    qc_final = build_circuit(final_gates)
    return qc_final

