def _matrices_equiv(U, V, tol=2e-2):
    ratio = None
    for i in range(8):
        for j in range(8):
            if abs(V[i, j]) > 1e-6:
                ratio = U[i, j] / V[i, j]
                break
        if ratio is not None:
            break
    if ratio is None:
        return False
    if abs(abs(ratio) - 1.0) > 0.1:
        return False
    return np.allclose(U, ratio * V, atol=tol)


