def solve():
    target = _target_matrix()
    ops = _original_ops()

    single_gates = ['x', 'y', 'z', 'h', 's', 'sdg', 't', 'tdg']
    two_gates = ['cx', 'cz', 'swap']
    two_qubit_pairs = [(0, 1), (1, 0), (0, 2), (2, 0), (1, 2), (2, 1)]
    rot_gates = ['rx', 'ry', 'rz']

    # First check if original (as given) already matches - unlikely, but safety check
    qc0 = _build_circuit(ops)
    U0 = Operator(qc0).data
    if _matrices_equiv(U0, target):
        return qc0

    n = len(ops)
    found_circuit = None

    for idx in range(n):
        name, qubits, params = ops[idx]
        candidates = []

        if name in single_gates:
            for g in single_gates:
                if g == name:
                    continue
                candidates.append((g, qubits, []))
            for q in range(3):
                if q != qubits[0]:
                    candidates.append((name, [q], []))
            candidates.append(('id', qubits, []))

        elif name in rot_gates:
            for g in rot_gates:
                if g != name:
                    candidates.append((g, qubits, params))
            candidates.append((name, qubits, [-params[0]]))
            for q in range(3):
                if q != qubits[0]:
                    candidates.append((name, [q], params))
            candidates.append(('id', qubits, []))

        elif name in two_gates:
            for g in two_gates:
                if g != name:
                    candidates.append((g, qubits, []))
            for pair in two_qubit_pairs:
                if list(pair) != qubits:
                    candidates.append((name, list(pair), []))
                    for g in two_gates:
                        if g != name:
                            candidates.append((g, list(pair), []))
            candidates.append(('id', qubits, []))

        for cand in candidates:
            new_ops = list(ops)
            new_ops[idx] = cand
            qc_try = _build_circuit(new_ops)
            U_try = Operator(qc_try).data
            if _matrices_equiv(U_try, target):
                found_circuit = qc_try
                break

        if found_circuit is not None:
            break

    if found_circuit is not None:
        return found_circuit

    # Fallback: try insertion of a single gate at each position (missing gate scenario)
    insert_candidates = []
    for g in single_gates:
        for q in range(3):
            insert_candidates.append((g, [q], []))
    for g in two_gates:
        for pair in two_qubit_pairs:
            insert_candidates.append((g, list(pair), []))

    for pos in range(n + 1):
        for cand in insert_candidates:
            new_ops = ops[:pos] + [cand] + ops[pos:]
            qc_try = _build_circuit(new_ops)
            U_try = Operator(qc_try).data
            if _matrices_equiv(U_try, target):
                return qc_try

    # If nothing found, return original circuit as last resort
    return _build_circuit(ops)

import numpy as np
import copy
from qiskit import QuantumCircuit
from qiskit.quantum_info import Operator


def _build_target():
    mapping = {
        '000': [('010', -0.0289+0.0409j), ('011', -0.1244-0.0880j),
                 ('110', 0.0344+0.0244j), ('111', 0.5695-0.8051j)],
        '001': [('010', 0.0696+0.7601j), ('110', 0.6400-0.0586j), ('111', 0.0059+0.0644j)],
        '010': [('001', 0.4883+0.5867j), ('100', -0.0414-0.0497j), ('101', 0.4940-0.4111j)],
        '011': [('000', -0.0257+0.1502j), ('001', -0.0494-0.0085j),
                 ('100', -0.9720-0.1665j), ('101', -0.0071+0.0416j)],
        '100': [('010', 0.0244-0.0344j), ('011', 0.8051+0.5695j),
                 ('110', 0.0409+0.0289j), ('111', 0.0880-0.1244j)],
        '101': [('010', -0.0586-0.6400j), ('011', -0.0644+0.0059j), ('110', 0.7601-0.0696j)],
        '110': [('000', 0.0497-0.0414j), ('001', -0.4111-0.4940j), ('101', 0.5867-0.4883j)],
        '111': [('000', 0.1665-0.9720j), ('001', 0.0416+0.0071j),
                 ('100', -0.1502-0.0257j), ('101', -0.0085+0.0494j)],
    }
    U = np.zeros((8, 8), dtype=complex)
    for in_str, outs in mapping.items():
        j = int(in_str, 2)
        for out_str, amp in outs:
            i = int(out_str, 2)
            U[i, j] = amp
    return U


_ORIGINAL_GATES = [
    ['rz', [0], [5.576163480144678]],
    ['x', [2], []],
    ['ry', [0], [3.272651387191274]],
    ['ry', [2], [5.736650091825691]],
    ['z', [0], []],
    ['h', [2], []],
    ['y', [2], []],
