    ['cz', [1, 0], []],
    ['t', [1], []],
    ['t', [1], []],
    ['y', [1], []],
    ['z', [0], []],
    ['t', [1], []],
    ['z', [1], []],
    ['z', [2], []],
    ['cx', [2, 0], []],
    ['t', [1], []],
    ['t', [1], []],
    ['rx', [2], [5.56552043588244]],
]


def _build_circuit(gates):
    qc = QuantumCircuit(3)
    for name, qubits, params in gates:
        if name == 'rz':
            qc.rz(params[0], qubits[0])
        elif name == 'rx':
            qc.rx(params[0], qubits[0])
        elif name == 'ry':
            qc.ry(params[0], qubits[0])
        elif name == 'x':
            qc.x(qubits[0])
        elif name == 'y':
            qc.y(qubits[0])
        elif name == 'z':
            qc.z(qubits[0])
        elif name == 'h':
            qc.h(qubits[0])
        elif name == 't':
            qc.t(qubits[0])
        elif name == 'tdg':
            qc.tdg(qubits[0])
        elif name == 's':
            qc.s(qubits[0])
        elif name == 'sdg':
            qc.sdg(qubits[0])
        elif name == 'sx':
            qc.sx(qubits[0])
        elif name == 'cx':
            qc.cx(qubits[0], qubits[1])
        elif name == 'cz':
            qc.cz(qubits[0], qubits[1])
        else:
            raise ValueError(f"unknown gate {name}")
    return qc


def _residual(Ucand, Utarget):
    M = Ucand.conjugate().T @ Utarget
    idx = np.unravel_index(np.argmax(np.abs(M)), M.shape)
    top = M[idx]
    if abs(top) < 1e-12:
        return 1e9
    phase = top / abs(top)
    diff = M - phase * np.eye(8)
    return float(np.max(np.abs(diff)))


def solve():
    U_target = _build_target()
    original_gates = copy.deepcopy(_ORIGINAL_GATES)
    n = len(original_gates)

    single_qubit_alts = ['x', 'y', 'z', 'h', 's', 'sdg', 't', 'tdg', 'sx']
    rotation_alts = ['rx', 'ry', 'rz']
    all_pairs = [(a, b) for a in range(3) for b in range(3) if a != b]

    def clone():
        return copy.deepcopy(original_gates)

    candidates = []

    # (A) swap qubits of a 2-qubit gate
    for i, g in enumerate(original_gates):
        if len(g[1]) == 2:
            c = clone()
            c[i] = [g[0], [g[1][1], g[1][0]], list(g[2])]
            candidates.append(c)

    # (B) change gate type
    for i, g in enumerate(original_gates):
        name, qubits, params = g
        if len(qubits) == 1:
            if name in rotation_alts:
                alts = [a for a in rotation_alts if a != name]
            else:
                alts = [a for a in single_qubit_alts if a != name]
            for a in alts:
                c = clone()
                newparams = list(params) if a in rotation_alts else []
                c[i] = [a, list(qubits), newparams]
                candidates.append(c)
        else:
            other = 'cz' if name == 'cx' else 'cx'
            c = clone()
            c[i] = [other, list(qubits), list(params)]
            candidates.append(c)

    # (C) move single-qubit gate to a different qubit
    for i, g in enumerate(original_gates):
        name, qubits, params = g
        if len(qubits) == 1:
            for q in range(3):
                if q != qubits[0]:
                    c = clone()
                    c[i] = [name, [q], list(params)]
                    candidates.append(c)

    # (D) change qubit pair of a 2-qubit gate
    for i, g in enumerate(original_gates):
        name, qubits, params = g
        if len(qubits) == 2:
            for p in all_pairs:
                if list(p) != qubits:
                    c = clone()
                    c[i] = [name, list(p), list(params)]
                    candidates.append(c)

    # (E) insert a missing gate
    two_qubit_inserts = [('cx', p) for p in all_pairs] + [('cz', (a, b)) for a, b in [(0, 1), (0, 2), (1, 2)]]
    for pos in range(n + 1):
        for gtype in single_qubit_alts:
            for q in range(3):
                c = clone()
                c.insert(pos, [gtype, [q], []])
                candidates.append(c)
        for gtype, pair in two_qubit_inserts:
            c = clone()
            c.insert(pos, [gtype, list(pair), []])
            candidates.append(c)

    best = None
    best_res = float('inf')

    for cand in candidates:
        try:
            qc = _build_circuit(cand)
            Uc = Operator(qc).data
        except Exception:
            continue
        r = _residual(Uc, U_target)
        if r < best_res:
            best_res = r
            best = cand

    if best is None:
        best = original_gates

    return _build_circuit(best)

