def solve():
    qasm_a = """
OPENQASM 2.0;
include "qelib1.inc";
qreg q[4];
t q[1];
s q[1];
cz q[2],q[3];
s q[1];
s q[2];
cz q[3],q[0];
rz(4.124196450638081) q[3];
rz(5.565039855165545) q[0];
s q[0];
cx q[0],q[1];
"""

    qasm_b = """
OPENQASM 2.0;
include "qelib1.inc";
qreg q[4];
t q[1];
s q[1];
cz q[2],q[3];
s q[1];
s q[2];
cz q[3],q[0];
rz(4.124196450638081) q[3];
rz(6.15661964562299) q[0];
s q[0];
cx q[0],q[1];
"""

    import qiskit.qasm2 as qasm2

    circ_a = qasm2.loads(qasm_a)
    circ_b = qasm2.loads(qasm_b)

    op_a = Operator(circ_a)
    op_b = Operator(circ_b)

    # Check equivalence up to global phase
    mat_a = op_a.data
    mat_b = op_b.data

    # Find index of max magnitude element to compute phase
    idx = np.unravel_index(np.argmax(np.abs(mat_a)), mat_a.shape)
    phase_a = mat_a[idx]
    phase_b = mat_b[idx]

    if np.abs(phase_b) < 1e-12:
        return False

    phase = phase_a / phase_b
    mat_b_adjusted = mat_b * phase

    return np.allclose(mat_a, mat_b_adjusted, atol=1e-8)

