        vec = vec / np.linalg.norm(vec)
        init_sv = Statevector(vec)

        sv_a = init_sv.evolve(circA)
        sv_b = init_sv.evolve(circB)

        a = sv_a.data
        b = sv_b.data

        # find phase alignment using the component with max magnitude in a
        idx = np.argmax(np.abs(a))
        if np.abs(b[idx]) < 1e-12:
            return False
        phase = a[idx] / b[idx]
        if not np.isclose(np.abs(phase), 1.0, atol=tol):
            return False

        b_aligned = b * phase

        if not np.allclose(a, b_aligned, atol=1e-5):
            return False

    return True

