def _pauli(name):
    if name == 'I':
        return np.eye(2, dtype=complex)
    if name == 'X':
        return np.array([[0, 1], [1, 0]], dtype=complex)
    if name == 'Y':
        return np.array([[0, -1j], [1j, 0]], dtype=complex)
    if name == 'Z':
        return np.array([[1, 0], [0, -1]], dtype=complex)
    raise ValueError(name)

def _build_hamiltonian():
    terms = [
        (0.2541, 'X', 'Y'),
        (-0.7526, 'X', 'Z'),
        (-0.5842, 'X', 'I'),
    ]
    H = np.zeros((4, 4), dtype=complex)
    for c, p0, p1 in terms:
        H += c * np.kron(_pauli(p0), _pauli(p1))
    return H, terms

def _append_term_evolution(qc, p0, p1, theta):
    # exp(-i*theta*(P0 on qubit0) tensor (P1 on qubit1))
    # Basis change to Z on qubit0
    if p0 == 'I':
        pass
    elif p0 == 'X':
        qc.h(0)
    elif p0 == 'Y':
        qc.rz(-np.pi/2, 0)
        qc.h(0)
    elif p0 == 'Z':
        pass

    # Basis change to Z on qubit1
    if p1 == 'I':
        pass
    elif p1 == 'X':
        qc.h(1)
    elif p1 == 'Y':
        qc.rz(-np.pi/2, 1)
        qc.h(1)
    elif p1 == 'Z':
        pass

    if p0 == 'I' and p1 == 'I':
        pass
    elif p0 == 'I' and p1 != 'I':
        qc.rz(2*theta, 1)
    elif p1 == 'I' and p0 != 'I':
        qc.rz(2*theta, 0)
    else:
        qc.cx(0, 1)
        qc.rz(2*theta, 1)
        qc.cx(0, 1)

    # Inverse basis change
    if p1 == 'I':
        pass
    elif p1 == 'X':
        qc.h(1)
    elif p1 == 'Y':
        qc.h(1)
        qc.rz(np.pi/2, 1)
    elif p1 == 'Z':
        pass

    if p0 == 'I':
        pass
    elif p0 == 'X':
        qc.h(0)
    elif p0 == 'Y':
        qc.h(0)
        qc.rz(np.pi/2, 0)
    elif p0 == 'Z':
        pass

def _trotter_circuit(terms, t, n_steps):
    qc = QuantumCircuit(2)
    for _ in range(n_steps):
        for c, p0, p1 in terms:
            theta = c * t / n_steps
            _append_term_evolution(qc, p0, p1, theta)
    return qc

def solve():
    t = 0.5
    H, terms = _build_hamiltonian()
    exact_U = expm(-1j * H * t)

    n_steps = 1
    max_steps = 200
    best_qc = None

    while n_steps <= max_steps:
        qc = _trotter_circuit(terms, t, n_steps)
        approx_U = Operator(qc).data
        fidelity = abs(np.trace(exact_U.conj().T @ approx_U)) / 4.0
        if fidelity > 0.99:
            best_qc = qc
            break
        n_steps += 1

    if best_qc is None:
        best_qc = _trotter_circuit(terms, t, max_steps)

    return best_qc

