            qc.rz(2 * theta, q)
        elif len(qubits) == 2:
            q0, q1 = qubits
            qc.cx(q0, q1)
            qc.rz(2 * theta, q1)
            qc.cx(q0, q1)

        # undo basis change
        for q in qubits:
            if term[q] == 'X':
                qc.h(q)

