def solve():
    n = 3
    terms = [
        (-1.5967, 'ZXX'),
        (-0.6182, 'ZZY'),
        (-0.1781, 'XYY'),
        (-1.9327, 'IIZ'),
        (-0.1992, 'IXI'),
    ]
    t = 1.0
    steps = 25  # number of Trotter steps for good fidelity
    dt = t / steps

    qc = QuantumCircuit(n)

    def apply_pauli_exp(circuit, pauli_str, angle):
        # Map string index i (0 = leftmost char) to qubit index n-1-i
        # (consistent with Qiskit little-endian qubit ordering)
        active = []
        for i, p in enumerate(pauli_str):
            if p != 'I':
                q = n - 1 - i
                active.append((p, q))

        if not active:
            return  # identity term contributes only a global phase

        # --- basis change to Z ---
        for p, q in active:
            if p == 'X':
                circuit.h(q)
            elif p == 'Y':
                circuit.rx(np.pi / 2, q)
            # 'Z' -> no change needed

        qubits_active = [q for _, q in active]

        # --- CNOT ladder to accumulate parity ---
        for k in range(len(qubits_active) - 1):
            circuit.cx(qubits_active[k], qubits_active[k + 1])

        # --- Z-rotation on last qubit encodes exp(-i*angle*Z...Z) ---
        circuit.rz(2 * angle, qubits_active[-1])

        # --- undo CNOT ladder ---
        for k in reversed(range(len(qubits_active) - 1)):
            circuit.cx(qubits_active[k], qubits_active[k + 1])

        # --- undo basis change ---
        for p, q in active:
            if p == 'X':
                circuit.h(q)
            elif p == 'Y':
                circuit.rx(-np.pi / 2, q)

    for _ in range(steps):
        for coeff, pstr in terms:
            angle = coeff * dt
            apply_pauli_exp(qc, pstr, angle)

    return qc

