def solve():
    t = 0.8
    terms = [
        (1.1815, 'X', 'Y'),
        (-1.9782, 'Z', 'Y'),
        (0.8636, 'X', 'I'),
        (0.4761, 'Y', 'Z'),
    ]

    n_steps = 20
    dt = t / n_steps

    qc = QuantumCircuit(2)

    def basis_forward(circ, qubit, pauli):
        # Transforms Pauli -> Z on given qubit (forward direction)
        if pauli == 'X':
            circ.h(qubit)
        elif pauli == 'Y':
            # U = H * Sdg  -> apply Sdg first, then H
            circ.rz(-np.pi / 2, qubit)  # equivalent to Sdg up to global phase
            circ.h(qubit)
        elif pauli == 'Z':
            pass
        elif pauli == 'I':
            pass
        else:
            raise ValueError(f"Unknown Pauli {pauli}")

    def basis_inverse(circ, qubit, pauli):
        # Inverse of basis_forward
        if pauli == 'X':
            circ.h(qubit)
        elif pauli == 'Y':
            # U^dagger = S * H -> apply H first, then S
            circ.h(qubit)
            circ.rz(np.pi / 2, qubit)  # equivalent to S up to global phase
        elif pauli == 'Z':
            pass
        elif pauli == 'I':
            pass
        else:
            raise ValueError(f"Unknown Pauli {pauli}")

    for _ in range(n_steps):
        for coeff, p0, p1 in terms:
            theta = coeff * dt  # exp(-i * theta * P0 P1) for this small step

            if p0 == 'I' and p1 == 'I':
                continue

            elif p1 == 'I':
                # Single-qubit term acting on qubit 0
                basis_forward(qc, 0, p0)
                qc.rz(2 * theta, 0)
                basis_inverse(qc, 0, p0)

            elif p0 == 'I':
                # Single-qubit term acting on qubit 1
                basis_forward(qc, 1, p1)
                qc.rz(2 * theta, 1)
                basis_inverse(qc, 1, p1)

            else:
                # Two-qubit term: P0 (qubit0) tensor P1 (qubit1)
                basis_forward(qc, 0, p0)
                basis_forward(qc, 1, p1)

                qc.cx(0, 1)
                qc.rz(2 * theta, 1)
                qc.cx(0, 1)

                basis_inverse(qc, 1, p1)
                basis_inverse(qc, 0, p0)

    return qc

