import numpy as np

def solve():
    n = 4
    dim = 2**n

    I = np.array([[1,0],[0,1]], dtype=complex)
    X = np.array([[0,1],[1,0]], dtype=complex)
    Y = np.array([[0,-1j],[1j,0]], dtype=complex)
    Z = np.array([[1,0],[0,-1]], dtype=complex)
    H = (1/np.sqrt(2))*np.array([[1,1],[1,-1]], dtype=complex)
    S = np.array([[1,0],[0,1j]], dtype=complex)
    T = np.array([[1,0],[0,np.exp(1j*np.pi/4)]], dtype=complex)

    def RX(theta):
        c = np.cos(theta/2)
        s = -1j*np.sin(theta/2)
        return np.array([[c, s],[s, c]], dtype=complex)

    def RZ(theta):
        return np.array([[np.exp(-1j*theta/2), 0],[0, np.exp(1j*theta/2)]], dtype=complex)

    def embed_op(pairs):
        ops = []
        for i in range(n-1, -1, -1):
            if i in pairs:
                ops.append(pairs[i])
            else:
                ops.append(I)
        result = ops[0]
        for op in ops[1:]:
            result = np.kron(result, op)
        return result

    def embed_1q(gate, q):
        return embed_op({q: gate})

    def cx_full(control, target):
        U = np.zeros((dim, dim), dtype=complex)
        for i in range(dim):
            bits = [(i >> b) & 1 for b in range(n)]
            c_bit = bits[control]
            if c_bit == 1:
                bits[target] ^= 1
            j = sum(bit << b for b, bit in enumerate(bits))
            U[j, i] = 1
        return U

    def depolarize_1(rho, q, p):
        Xf = embed_1q(X, q)
        Yf = embed_1q(Y, q)
        Zf = embed_1q(Z, q)
        return (1-p)*rho + (p/3)*(Xf@rho@Xf.conj().T + Yf@rho@Yf.conj().T + Zf@rho@Zf.conj().T)

    def depolarize_2(rho, q1, q2, p):
        paulis = [I, X, Y, Z]
        total = np.zeros_like(rho)
        for p1 in paulis:
            for p2 in paulis:
                if (p1 is I) and (p2 is I):
                    continue
                op = embed_op({q1: p1, q2: p2})
                total += op@rho@op.conj().T
        return (1-p)*rho + (p/15)*total

    # Gate sequence: (type, qubits, param)
    gates = [
        ('s', [1], None),
        ('y', [2], None),
        ('h', [1], None),
        ('rx', [0], 0.139009),
        ('t', [1], None),
        ('h', [3], None),
        ('rx', [3], 4.835409),
        ('z', [2], None),
        ('cx', [3,1], None),
        ('cx', [2,0], None),
        ('rz', [0], 2.768936),
        ('rz', [3], 0.243076),
        ('s', [2], None),
        ('z', [3], None),
        ('x', [2], None),
    ]

    p1_noise = 0.003
    p2_noise = 0.015

    # Build ideal statevector
    psi = np.zeros((dim,), dtype=complex)
    psi[0] = 1.0

    # Build noisy density matrix
    rho = np.zeros((dim, dim), dtype=complex)
    rho[0,0] = 1.0

    def gate_unitary(gtype, qubits, param):
        if gtype == 's':
            return embed_1q(S, qubits[0])
        elif gtype == 'y':
            return embed_1q(Y, qubits[0])
        elif gtype == 'h':
            return embed_1q(H, qubits[0])
        elif gtype == 'rx':
            return embed_1q(RX(param), qubits[0])
        elif gtype == 't':
            return embed_1q(T, qubits[0])
        elif gtype == 'z':
            return embed_1q(Z, qubits[0])
        elif gtype == 'x':
            return embed_1q(X, qubits[0])
        elif gtype == 'rz':
            return embed_1q(RZ(param), qubits[0])
        elif gtype == 'cx':
            return cx_full(qubits[0], qubits[1])
        else:
            raise ValueError("Unknown gate")

    for gtype, qubits, param in gates:
        U = gate_unitary(gtype, qubits, param)

        # ideal state evolution
        psi = U @ psi

        # noisy density matrix evolution
        rho = U @ rho @ U.conj().T

        if len(qubits) == 1:
            rho = depolarize_1(rho, qubits[0], p1_noise)
        else:
            rho = depolarize_2(rho, qubits[0], qubits[1], p2_noise)

    fidelity = np.real(np.conj(psi) @ rho @ psi)
    return float(fidelity)

