        for input_str, terms in raw_mappings.items():
            if endianness == 'msb_first':
                col = int(input_str, 2)
            else:
                col = int(input_str[::-1], 2)

            for val, output_str in terms:
                if endianness == 'msb_first':
                    row = int(output_str, 2)
                else:
                    row = int(output_str[::-1], 2)
                U[row, col] = val
        return U

    target_msb = get_target_unitary('msb_first')
    target_lsb = get_target_unitary('lsb_first')

    buggy_gates = [
        ('cz', (0, 2)),
        ('cx', (1, 0)),
        ('s', (0,)),
        ('cz', (2, 1)),
        ('x', (2,)),
        ('h', (1,)),
        ('s', (1,)),
        ('t', (2,)),
        ('cx', (1, 0)),
        ('cx', (0, 2)),
        ('t', (2,)),
        ('cz', (2, 1)),
        ('t', (0,)),
        ('cz', (2, 1))
    ]

    def build_circuit(gates):
        qc = QuantumCircuit(3)
        for gate, qubits in gates:
            if gate == 'x':
                qc.x(qubits[0])
