            for q2 in range(3):
                if q1 != q2:
                    for g in ['cx', 'cz', 'swap']:
                        cand = buggy_gates[:i] + [(g, (q1, q2))] + buggy_gates[i:]
                        res = check(cand)
                        if res: return res

    return build_circuit(buggy_gates)

