    for i in range(len(instructions) + 1):
        for g in one_qubit_gates:
            for q_idx in range(3):
                q = buggy_qc.qubits[q_idx]
                test_insts = instructions[:i] + [(g, (q,))] + instructions[i:]
                qc = QuantumCircuit(3)
                for op_t, qbs_t in test_insts:
                    qc.append(op_t, qbs_t)
                if get_fidelity(qc) > 0.99:
                    return qc
        for g in two_qubit_gates:
            for q0_idx in range(3):
