import qiskit.qasm2
from qiskit import QuantumCircuit
from qiskit.quantum_info import Statevector
import itertools

def solve():
    qasm_str = """OPENQASM 2.0;
include "qelib1.inc";
qreg q[3];
rx(4.390097046656369) q[1];
t q[0];
x q[2];
z q[1];
t q[1];
rx(-0.45032746271864055) q[1];
h q[1];
h q[0];
z q[0];
x q[1];
cz q[2],q[1];
cx q[2],q[0];
cz q[1],q[0];
ry(3.2460947028273317) q[2];
t q[2];"""

    expected = {
        '010': 0.4165,
        '011': 0.4165,
        '000': 0.0821,
        '001': 0.0821,
        '110': 0.0011,
        '111': 0.0011,
        '100': 0.0002,
        '101': 0.0002
    }

    def tvd(p1, p2):
        keys = set(p1.keys()) | set(p2.keys())
        return 0.5 * sum(abs(p1.get(k, 0.0) - p2.get(k, 0.0)) for k in keys)

    def get_probs(qc):
        try:
            sv = Statevector.from_instruction(qc)
            return sv.probabilities_dict()
        except Exception:
            return {}

    orig_qc = qiskit.qasm2.loads(qasm_str)

    if tvd(get_probs(orig_qc), expected) < 0.01:
        return orig_qc

    def get_instructions(qc):
        insts = []
        for inst in qc.data:
            if hasattr(inst, 'operation'):
                insts.append((inst.operation, inst.qubits, inst.clbits))
            else:
                insts.append((inst[0], inst[1], inst[2]))
        return insts

    def rebuild_circuit(orig_qc, insts):
        qc = QuantumCircuit(orig_qc.num_qubits)
        for op, qubits, clbits in insts:
            new_qubits = [qc.qubits[orig_qc.find_bit(q).index] for q in qubits]
            qc.append(op, new_qubits, clbits)
        return qc

    instructions = get_instructions(orig_qc)

    # 1. Remove one gate
    for i in range(len(instructions)):
        cand_instructions = instructions[:i] + instructions[i+1:]
        cand_qc = rebuild_circuit(orig_qc, cand_instructions)
        if tvd(get_probs(cand_qc), expected) < 0.01:
            return cand_qc

    # 2. Negate parameter
    for i, (op, qubits, clbits) in enumerate(instructions):
        if hasattr(op, 'params') and len(op.params) > 0:
            new_op = op.__class__(-op.params[0])
            cand_instructions = instructions.copy()
            cand_instructions[i] = (new_op, qubits, clbits)
            cand_qc = rebuild_circuit(orig_qc, cand_instructions)
            if tvd(get_probs(cand_qc), expected) < 0.01:
                return cand_qc

    # 3. Swap qubits for 1-qubit gates
    for i, (op, qubits, clbits) in enumerate(instructions):
        if len(qubits) == 1:
            orig_q_idx = orig_qc.find_bit(qubits[0]).index
            for new_q_idx in range(orig_qc.num_qubits):
                if new_q_idx == orig_q_idx:
                    continue
                new_qubits = (orig_qc.qubits[new_q_idx],)
                cand_instructions = instructions.copy()
                cand_instructions[i] = (op, new_qubits, clbits)
                cand_qc = rebuild_circuit(orig_qc, cand_instructions)
                if tvd(get_probs(cand_qc), expected) < 0.01:
                    return cand_qc

    # 4. Swap qubits for 2-qubit gates
    for i, (op, qubits, clbits) in enumerate(instructions):
        if len(qubits) == 2:
            new_qubits = (qubits[1], qubits[0])
            cand_instructions = instructions.copy()
            cand_instructions[i] = (op, new_qubits, clbits)
            cand_qc = rebuild_circuit(orig_qc, cand_instructions)
            if tvd(get_probs(cand_qc), expected) < 0.01:
                return cand_qc

    # 5. Change qubits of 2-qubit gates to other pairs
    for i, (op, qubits, clbits) in enumerate(instructions):
        if len(qubits) == 2:
            orig_indices = [orig_qc.find_bit(q).index for q in qubits]
            for p in itertools.permutations(range(orig_qc.num_qubits), 2):
                if list(p) == orig_indices:
                    continue
                new_qubits = tuple(orig_qc.qubits[idx] for idx in p)
                cand_instructions = instructions.copy()
                cand_instructions[i] = (op, new_qubits, clbits)
                cand_qc = rebuild_circuit(orig_qc, cand_instructions)
                if tvd(get_probs(cand_qc), expected) < 0.01:
                    return cand_qc

    # 6. Substitute gate types
    from qiskit.circuit.library import (
        XGate, YGate, ZGate, HGate, SGate, SdgGate, TGate, TdgGate, CXGate, CZGate
    )
    substitutions = {
        TGate: [TdgGate, SGate, ZGate],
        TdgGate: [TGate],
        SGate: [SdgGate, TGate, ZGate],
        SdgGate: [SGate],
        XGate: [YGate, ZGate, HGate],
        YGate: [XGate, ZGate, HGate],
        ZGate: [XGate, YGate, HGate, TGate, SGate],
        HGate: [XGate, YGate, ZGate],
        CXGate: [CZGate],
        CZGate: [CXGate]
    }
    for i, (op, qubits, clbits) in enumerate(instructions):
        op_type = type(op)
        if op_type in substitutions:
            for new_op_class in substitutions[op_type]:
                new_op = new_op_class()
                cand_instructions = instructions.copy()
                cand_instructions[i] = (new_op, qubits, clbits)
                cand_qc = rebuild_circuit(orig_qc, cand_instructions)
                if tvd(get_probs(cand_qc), expected) < 0.01:
                    return cand_qc

    # 7. Swap adjacent gates
    for i in range(len(instructions) - 1):
        cand_instructions = instructions.copy()
        cand_instructions[i], cand_instructions[i+1] = cand_instructions[i+1], cand_instructions[i]
        cand_qc = rebuild_circuit(orig_qc, cand_instructions)
        if tvd(get_probs(cand_qc), expected) < 0.01:
            return cand_qc

    return orig_qc

