    }

    orig_circuit = qiskit.qasm2.loads(qasm_str)

    def check_match(circ):
        try:
            sv = Statevector.from_instruction(circ)
            probs = sv.probabilities_dict()

            # Check standard
            tvd = 0.0
            for k, v in expected_dict.items():
                tvd += abs(probs.get(k, 0.0) - v)
            tvd /= 2.0
            if tvd < 1e-3:
                return True

            # Check reversed
            tvd_rev = 0.0
            for k, v in expected_dict.items():
                k_rev = k[::-1]
                tvd_rev += abs(probs.get(k_rev, 0.0) - v)
            tvd_rev /= 2.0
            if tvd_rev < 1e-3:
