        op = inst.operation

        if len(qubits) == 1:
            # Try standard 1-qubit gates
            gates_to_try = [HGate(), XGate(), YGate(), ZGate(), SGate(), TGate(), SdgGate(), TdgGate(), SXGate(), SXdgGate()]

