            if hasattr(op, 'params') and len(op.params) > 0:
                theta = op.params[0]
                for t in [-theta, theta + np.pi, theta - np.pi]:
                    gates_to_try.extend([RXGate(t), RYGate(t), RZGate(t)])
                # Also try changing axis with same theta
                gates_to_try.extend([RXGate(theta), RYGate(theta), RZGate(theta)])

            for g in gates_to_try:
                new_circ = orig_circuit.copy()
                new_circ.data[i] = CircuitInstruction(g, qubits, clbits)
                if check_match(new_circ):
                    return new_circ

        elif len(qubits) == 2:
            # Try swapping qubits
            new_circ = orig_circuit.copy()
            new_circ.data[i] = CircuitInstruction(op, [qubits[1], qubits[0]], clbits)
            if check_match(new_circ):
                return new_circ

            # Try changing gate type
            gates_to_try = [CXGate(), CZGate(), SwapGate(), CYGate(), CHGate()]
            for g in gates_to_try:
                # Try with original qubit order
                new_circ = orig_circuit.copy()
                new_circ.data[i] = CircuitInstruction(g, qubits, clbits)
                if check_match(new_circ):
                    return new_circ
                # Try with swapped qubit order
                new_circ = orig_circuit.copy()
                new_circ.data[i] = CircuitInstruction(g, [qubits[1], qubits[0]], clbits)
                if check_match(new_circ):
