    for i in range(n_instructions - 1):
        new_circ = orig_circuit.copy()
        new_circ.data[i], new_circ.data[i+1] = new_circ.data[i+1], new_circ.data[i]
        if check_match(new_circ):
            return new_circ

    # If no single-gate modification works, return original (fallback)
    return orig_circuit

