ry(1.3331731288912216) q[1];
rx(5.244222112794835) q[2];
rz(0.681303639896158) q[1];
cz q[3],q[2];
cx q[1],q[0];
x q[2];
cx q[2],q[3];"""

    circuit = qasm2.loads(qasm_str)

    expected = {
        0: 0.2190,
        13: 0.2190,
        1: 0.1512,
        12: 0.1512,
        3: 0.0768,
        14: 0.0768,
        2: 0.0530,
        15: 0.0530,
    }
    expected_probs = np.zeros(16)
    for k, v in expected.items():
        expected_probs[k] = v

    def get_tvd(qc):
        try:
            sv = Statevector.from_instruction(qc)
            probs = sv.probabilities()
            return 0.5 * np.sum(np.abs(probs - expected_probs))
        except Exception:
            return 1.0

    if get_tvd(circuit) < 1e-3:
        return circuit

    instructions = list(circuit.data)
    q_objs = circuit.qubits

    def reconstruct(insts):
        qc = QuantumCircuit(4)
        for inst in insts:
            qc.append(inst.operation, inst.qubits, inst.clbits)
        return qc

    # 1. Try removing each gate
    for idx in range(len(instructions)):
        modified = instructions[:idx] + instructions[idx+1:]
        qc = reconstruct(modified)
        if get_tvd(qc) < 1e-3:
            return qc

    # 2. Try modifying each gate
    for idx in range(len(instructions)):
        inst = instructions[idx]
        op = inst.operation
        num_qubits = len(inst.qubits)

        if num_qubits == 1:
            # Try changing qubit
            for q in range(4):
                if inst.qubits[0] != q_objs[q]:
                    new_inst = CircuitInstruction(op, (q_objs[q],), inst.clbits)
                    modified = instructions[:idx] + [new_inst] + instructions[idx+1:]
                    qc = reconstruct(modified)
                    if get_tvd(qc) < 1e-3:
                        return qc

            # Try changing gate type
            if op.name in ['x', 'y', 'z', 'h']:
                for gate_class in [XGate, YGate, ZGate, HGate]:
                    new_op = gate_class()
                    if new_op.name != op.name:
                        new_inst = CircuitInstruction(new_op, inst.qubits, inst.clbits)
                        modified = instructions[:idx] + [new_inst] + instructions[idx+1:]
                        qc = reconstruct(modified)
                        if get_tvd(qc) < 1e-3:
                            return qc
            elif op.name in ['rx', 'ry', 'rz']:
                param = op.params[0]
                for gate_class in [RXGate, RYGate, RZGate]:
                    for p in [param, -param, param + np.pi, param - np.pi, param + np.pi/2, param - np.pi/2]:
                        new_op = gate_class(p)
                        if new_op.name != op.name or p != param:
                            new_inst = CircuitInstruction(new_op, inst.qubits, inst.clbits)
                            modified = instructions[:idx] + [new_inst] + instructions[idx+1:]
                            qc = reconstruct(modified)
                            if get_tvd(qc) < 1e-3:
                                return qc

        elif num_qubits == 2:
            # Try changing qubits
            for q1 in range(4):
                for q2 in range(4):
                    if q1 != q2 and inst.qubits != (q_objs[q1], q_objs[q2]):
                        new_inst = CircuitInstruction(op, (q_objs[q1], q_objs[q2]), inst.clbits)
                        modified = instructions[:idx] + [new_inst] + instructions[idx+1:]
                        qc = reconstruct(modified)
                        if get_tvd(qc) < 1e-3:
                            return qc

            # Try changing gate type
            if op.name in ['cx', 'cz']:
                new_op = CZGate() if op.name == 'cx' else CXGate()
                new_inst = CircuitInstruction(new_op, inst.qubits, inst.clbits)
                modified = instructions[:idx] + [new_inst] + instructions[idx+1:]
                qc = reconstruct(modified)
                if get_tvd(qc) < 1e-3:
                    return qc

    return circuit

