    expected = {
        0: 0.1067, 3: 0.1067, 8: 0.1067, 11: 0.1067,
        13: 0.1067, 14: 0.1067, 5: 0.1067, 6: 0.1067,
        2: 0.0183, 9: 0.0183, 10: 0.0183, 12: 0.0183,
        15: 0.0183, 1: 0.0183, 7: 0.0183, 4: 0.0183
    }

    def get_tvd(qc):
        try:
            sv = Statevector.from_instruction(qc)
            probs = sv.probabilities()
            tvd = 0.5 * sum(abs(probs[i] - expected[i]) for i in range(16))
            return tvd
        except Exception:
            return 1.0

    orig_tvd = get_tvd(circuit)
    if orig_tvd < 0.01:
        return circuit

    n_instructions = len(circuit.data)

    for i in range(n_instructions):
        inst = circuit.data[i]
        op = inst.operation
        qubits = inst.qubits
        clbits = inst.clbits

        # 1. Try removing the gate
        tmp_qc = circuit.copy()
