                    new_op = type(op)(new_theta)
                    tmp_qc = circuit.copy()
                    tmp_qc.data[i] = CircuitInstruction(new_op, [q], clbits)
                    if get_tvd(tmp_qc) < 0.01:
                        return tmp_qc

        elif len(qubits) == 2:
            q0, q1 = qubits[0], qubits[1]
            # 5. Try CX and CZ with both orientations
            for g in [CXGate(), CZGate()]:
                for qs in [(q0, q1), (q1, q0)]:
                    tmp_qc = circuit.copy()
                    tmp_qc.data[i] = CircuitInstruction(g, list(qs), clbits)
                    if get_tvd(tmp_qc) < 0.01:
                        return tmp_qc

            # 6. Try all pairs of qubits
            for q_pair in itertools.permutations(circuit.qubits, 2):
                if list(q_pair) != [q0, q1]:
