def solve():
    import numpy as np
    from qiskit import QuantumCircuit
    from qiskit.quantum_info import Statevector

    expected = np.array([0.0, 0.1617, 0.0, 0.3383, 0.3383, 0.0, 0.1617, 0.0])

    def matches(qc):
        try:
            sv = Statevector.from_instruction(qc)
            probs = sv.probabilities()
            return np.allclose(probs, expected, atol=1e-3)
        except Exception:
            return False

    qc_orig = QuantumCircuit(3)
    qc_orig.y(0)
    qc_orig.z(0)
    qc_orig.rx(2.9023731792410192, 1)
    qc_orig.ry(5.200616505001642, 1)
    qc_orig.cz(0, 2)
    qc_orig.cz(2, 0)
    qc_orig.y(2)
    qc_orig.cx(2, 0)
    qc_orig.s(1)
    qc_orig.h(0)
    qc_orig.t(0)
    qc_orig.s(0)
    qc_orig.cz(2, 1)
    qc_orig.cx(2, 1)
    qc_orig.cz(1, 0)
    qc_orig.rz(1.4461854753991825, 0)
    qc_orig.h(1)
    qc_orig.cx(0, 2)
    qc_orig.s(0)
    qc_orig.s(1)

    if matches(qc_orig):
        return qc_orig

    gates = []
    for inst in qc_orig.data:
        gates.append({
            'name': inst.operation.name,
            'params': inst.operation.params,
            'qubits': [qc_orig.qubits.index(q) for q in inst.qubits]
        })

    def rebuild(gates_list):
        qc = QuantumCircuit(3)
        for g in gates_list:
            name = g['name']
            params = g['params']
            q = g['qubits']
            if name == 'y':
                qc.y(q[0])
            elif name == 'z':
                qc.z(q[0])
            elif name == 'x':
                qc.x(q[0])
            elif name == 'rx':
                qc.rx(params[0], q[0])
            elif name == 'ry':
                qc.ry(params[0], q[0])
            elif name == 'rz':
                qc.rz(params[0], q[0])
            elif name == 'cz':
                qc.cz(q[0], q[1])
            elif name == 'cx':
                qc.cx(q[0], q[1])
            elif name == 's':
                qc.s(q[0])
            elif name == 'sdg':
                qc.sdg(q[0])
            elif name == 't':
                qc.t(q[0])
            elif name == 'tdg':
                qc.tdg(q[0])
            elif name == 'h':
                qc.h(q[0])
        return qc

    # Try 1: Remove one gate
    for i in range(len(gates)):
        temp_gates = gates[:i] + gates[i+1:]
        qc_temp = rebuild(temp_gates)
        if matches(qc_temp):
            return qc_temp

    # Try 2: Modify one gate's qubits
    for i in range(len(gates)):
        g = gates[i]
        if len(g['qubits']) == 1:
            for q_new in [0, 1, 2]:
                if q_new != g['qubits'][0]:
                    temp_gates = [dict(x) for x in gates]
                    temp_gates[i]['qubits'] = [q_new]
                    qc_temp = rebuild(temp_gates)
                    if matches(qc_temp):
                        return qc_temp
        elif len(g['qubits']) == 2:
            # Try swapping control and target
            temp_gates = [dict(x) for x in gates]
            temp_gates[i]['qubits'] = [g['qubits'][1], g['qubits'][0]]
            qc_temp = rebuild(temp_gates)
            if matches(qc_temp):
                return qc_temp

            # Try other qubit pairs
            for q0 in [0, 1, 2]:
                for q1 in [0, 1, 2]:
                    if q0 != q1 and [q0, q1] != g['qubits']:
                        temp_gates = [dict(x) for x in gates]
                        temp_gates[i]['qubits'] = [q0, q1]
                        qc_temp = rebuild(temp_gates)
                        if matches(qc_temp):
                            return qc_temp

    # Try 3: Modify one gate's type
    for i in range(len(gates)):
        g = gates[i]
        name = g['name']
        if len(g['qubits']) == 1:
            if name in ['rx', 'ry', 'rz']:
                for alt in ['rx', 'ry', 'rz']:
                    if alt != name:
                        temp_gates = [dict(x) for x in gates]
                        temp_gates[i]['name'] = alt
                        qc_temp = rebuild(temp_gates)
                        if matches(qc_temp):
                            return qc_temp
            else:
                for alt in ['x', 'y', 'z', 'h', 's', 'sdg', 't', 'tdg']:
                    if alt != name:
                        temp_gates = [dict(x) for x in gates]
                        temp_gates[i]['name'] = alt
                        qc_temp = rebuild(temp_gates)
                        if matches(qc_temp):
                            return qc_temp
        elif len(g['qubits']) == 2:
            for alt in ['cx', 'cz']:
                if alt != name:
                    temp_gates = [dict(x) for x in gates]
                    temp_gates[i]['name'] = alt
                    qc_temp = rebuild(temp_gates)
                    if matches(qc_temp):
                        return qc_temp

    # Try 4: Change sign of parameter for rx, ry, rz
    for i in range(len(gates)):
        g = gates[i]
        if g['name'] in ['rx', 'ry', 'rz']:
            temp_gates = [dict(x) for x in gates]
            temp_gates[i]['params'] = [-g['params'][0]]
            qc_temp = rebuild(temp_gates)
            if matches(qc_temp):
                return qc_temp

    return qc_orig

