include "qelib1.inc";
qreg q[4];
rz(2.441160786815985) q[2];
rx(2.947217229918511) q[3];
y q[2];
s q[1];
rz(4.334434171142473) q[2];
rz(4.177097469236492) q[3];
t q[1];
t q[1];
cx q[3],q[1];
z q[0];
z q[2];
x q[0];
rx(2.951727016556071) q[0];
ry(0.5646865487388301) q[3];
cx q[0],q[3];
cz q[2],q[3];
cz q[3],q[0];
y q[2];
cz q[2],q[3];
y q[0];
h q[1];
cz q[3],q[1];
cz q[2],q[3];
cz q[0],q[2];
ry(0.42172113258774646) q[2];
x q[3];
ry(2.2118029583969134) q[3];
rx(3.696321875949893) q[3];
rx(4.542022582014654) q[0];"""

    circuit = qasm2.loads(qasm_str)

    expected_dict = {
        '0000': 0.2239, '0010': 0.2028, '0001': 0.1758, '1011': 0.1372,
        '1010': 0.0717, '0011': 0.0665, '1000': 0.0505, '1001': 0.0279,
        '0100': 0.0103, '0110': 0.0093, '0101': 0.0081, '1111': 0.0063,
        '1110': 0.0033, '0111': 0.0030, '1100': 0.0023, '1101': 0.0013
    }

    def tvd(p1, p2):
        keys = set(p1.keys()) | set(p2.keys())
        return 0.5 * sum(abs(p1.get(k, 0) - p2.get(k, 0)) for k in keys)

    sv = Statevector.from_instruction(circuit)
    orig_tvd = tvd(sv.probabilities_dict(), expected_dict)
    if orig_tvd < 0.01:
        return circuit

    best_circ = circuit
    best_tvd = orig_tvd

    # 1. Try deleting a gate
    for i in range(len(circuit.data)):
        new_circ = circuit.copy()
        new_circ.data = circuit.data[:i] + circuit.data[i+1:]
        try:
            sv = Statevector.from_instruction(new_circ)
            curr_tvd = tvd(sv.probabilities_dict(), expected_dict)
            if curr_tvd < best_tvd:
                best_tvd = curr_tvd
                best_circ = new_circ
        except Exception:
            pass

