                new_params = list(gate.params)
                new_params[param_idx] = -new_params[param_idx]
                new_gate = gate.copy()
                new_gate.params = new_params
                new_inst = qiskit.circuit.CircuitInstruction(new_gate, inst.qubits, inst.clbits)
                new_circ = circuit.copy()
                new_circ.data = circuit.data[:i] + [new_inst] + circuit.data[i+1:]
                try:
                    sv = Statevector.from_instruction(new_circ)
                    curr_tvd = tvd(sv.probabilities_dict(), expected_dict)
                    if curr_tvd < best_tvd:
                        best_tvd = curr_tvd
                        best_circ = new_circ
                except Exception:
                    pass

    # 3. Try changing gate types
    one_q_gates = ['x', 'y', 'z', 'h', 's', 't']
    one_q_param_gates = ['rx', 'ry', 'rz']
    for i in range(len(circuit.data)):
        inst = circuit.data[i]
        gate = inst.operation
        qubits = inst.qubits
        clbits = inst.clbits

        if len(qubits) == 1:
            if gate.name in one_q_gates:
                for g_name in one_q_gates:
                    if g_name != gate.name:
                        if g_name == 'x': new_gate = lib.XGate()
                        elif g_name == 'y': new_gate = lib.YGate()
                        elif g_name == 'z': new_gate = lib.ZGate()
                        elif g_name == 'h': new_gate = lib.HGate()
                        elif g_name == 's': new_gate = lib.SGate()
                        elif g_name == 't': new_gate = lib.TGate()
                        new_inst = qiskit.circuit.CircuitInstruction(new_gate, qubits, clbits)
                        new_circ = circuit.copy()
                        new_circ.data = circuit.data[:i] + [new_inst] + circuit.data[i+1:]
                        try:
                            sv = Statevector.from_instruction(new_circ)
                            curr_tvd = tvd(sv.probabilities_dict(), expected_dict)
                            if curr_tvd < best_tvd:
                                best_tvd = curr_tvd
                                best_circ = new_circ
                        except Exception:
                            pass
            elif gate.name in one_q_param_gates:
                for g_name in one_q_param_gates:
                    if g_name != gate.name:
                        if g_name == 'rx': new_gate = lib.RXGate(*gate.params)
                        elif g_name == 'ry': new_gate = lib.RYGate(*gate.params)
                        elif g_name == 'rz': new_gate = lib.RZGate(*gate.params)
                        new_inst = qiskit.circuit.CircuitInstruction(new_gate, qubits, clbits)
                        new_circ = circuit.copy()
                        new_circ.data = circuit.data[:i] + [new_inst] + circuit.data[i+1:]
                        try:
                            sv = Statevector.from_instruction(new_circ)
                            curr_tvd = tvd(sv.probabilities_dict(), expected_dict)
                            if curr_tvd < best_tvd:
                                best_tvd = curr_tvd
                                best_circ = new_circ
                        except Exception:
                            pass
