                    if g_name != gate.name:
                        if g_name == 'cx': new_gate = lib.CXGate()
                        elif g_name == 'cz': new_gate = lib.CZGate()
                        new_inst = qiskit.circuit.CircuitInstruction(new_gate, qubits, clbits)
                        new_circ = circuit.copy()
                        new_circ.data = circuit.data[:i] + [new_inst] + circuit.data[i+1:]
                        try:
                            sv = Statevector.from_instruction(new_circ)
                            curr_tvd = tvd(sv.probabilities_dict(), expected_dict)
                            if curr_tvd < best_tvd:
                                best_tvd = curr_tvd
                                best_circ = new_circ
                        except Exception:
                            pass

    # 4. Try swapping qubits for 2-qubit gates
    for i in range(len(circuit.data)):
        inst = circuit.data[i]
        gate = inst.operation
        qubits = inst.qubits
        clbits = inst.clbits
        if len(qubits) == 2:
            new_inst = qiskit.circuit.CircuitInstruction(gate, [qubits[1], qubits[0]], clbits)
            new_circ = circuit.copy()
            new_circ.data = circuit.data[:i] + [new_inst] + circuit.data[i+1:]
            try:
                sv = Statevector.from_instruction(new_circ)
                curr_tvd = tvd(sv.probabilities_dict(), expected_dict)
                if curr_tvd < best_tvd:
                    best_tvd = curr_tvd
                    best_circ = new_circ
            except Exception:
                pass

    # 5. Try changing qubits
    for i in range(len(circuit.data)):
        inst = circuit.data[i]
        gate = inst.operation
        qubits = inst.qubits
        clbits = inst.clbits
        if len(qubits) == 1:
            for q_idx in range(4):
                if circuit.qubits[q_idx] != qubits[0]:
                    new_inst = qiskit.circuit.CircuitInstruction(gate, [circuit.qubits[q_idx]], clbits)
                    new_circ = circuit.copy()
                    new_circ.data = circuit.data[:i] + [new_inst] + circuit.data[i+1:]
                    try:
                        sv = Statevector.from_instruction(new_circ)
                        curr_tvd = tvd(sv.probabilities_dict(), expected_dict)
                        if curr_tvd < best_tvd:
                            best_tvd = curr_tvd
                            best_circ = new_circ
                    except Exception:
                        pass
        elif len(qubits) == 2:
            for q1 in range(4):
                for q2 in range(4):
                    if q1 != q2 and (circuit.qubits[q1] != qubits[0] or circuit.qubits[q2] != qubits[1]):
                        new_inst = qiskit.circuit.CircuitInstruction(gate, [circuit.qubits[q1], circuit.qubits[q2]], clbits)
                        new_circ = circuit.copy()
                        new_circ.data = circuit.data[:i] + [new_inst] + circuit.data[i+1:]
                        try:
                            sv = Statevector.from_instruction(new_circ)
                            curr_tvd = tvd(sv.probabilities_dict(), expected_dict)
                            if curr_tvd < best_tvd:
                                best_tvd = curr_tvd
                                best_circ = new_circ
                        except Exception:
                            pass

    # 6. Try swapping adjacent gates
    for i in range(len(circuit.data) - 1):
        new_data = list(circuit.data)
        new_data[i], new_data[i+1] = new_data[i+1], new_data[i]
        new_circ = circuit.copy()
        new_circ.data = new_data
        try:
            sv = Statevector.from_instruction(new_circ)
            curr_tvd = tvd(sv.probabilities_dict(), expected_dict)
            if curr_tvd < best_tvd:
                best_tvd = curr_tvd
                best_circ = new_circ
        except Exception:
            pass

    return best_circ

