import numpy as np
from qiskit import qasm2
from qiskit.quantum_info import Operator

def solve():
    qasm_a = """OPENQASM 2.0;
include "qelib1.inc";
qreg q[4];
t q[1];
s q[1];
cz q[2],q[3];
s q[1];
s q[2];
cz q[3],q[0];
rz(4.124196450638081) q[3];
rz(5.565039855165545) q[0];
s q[0];
cx q[0],q[1];"""

    qasm_b = """OPENQASM 2.0;
include "qelib1.inc";
qreg q[4];
t q[1];
s q[1];
cz q[2],q[3];
s q[1];
s q[2];
cz q[3],q[0];
rz(4.124196450638081) q[3];
rz(6.15661964562299) q[0];
s q[0];
cx q[0],q[1];"""

    circ_a = qasm2.loads(qasm_a)
    circ_b = qasm2.loads(qasm_b)

    op_a = Operator(circ_a)
    op_b = Operator(circ_b)

    mat_a = op_a.data
    mat_b = op_b.data

    idx = np.argmax(np.abs(mat_a))
    phase = mat_b.flat[idx] / mat_a.flat[idx]

    return bool(np.allclose(mat_b, phase * mat_a))

