import numpy as np
from scipy.optimize import minimize
from qiskit.quantum_info import SparsePauliOp, Statevector
from qiskit import QuantumCircuit

def solve():
    np.random.seed(42)
    paulis = ["IZIZ", "YIIX", "IIZX", "XZZY", "IXIY", "YZZX", "XYIX", "ZZZY"]
    coeffs = [-1.007755, 1.404643, -0.145175, 0.992688, 1.420416, 0.715544, -1.103182, 0.258612]
    H = SparsePauliOp(paulis, coeffs)

    def ansatz(params):
        qc = QuantumCircuit(4)
        param_idx = 0
        for layer in range(3):
            for i in range(4):
                qc.ry(params[param_idx], i)
                qc.rz(params[param_idx+1], i)
                param_idx += 2
            for i in range(3):
                qc.cx(i, i+1)
            qc.cx(3, 0)
        for i in range(4):
            qc.ry(params[param_idx], i)
            qc.rz(params[param_idx+1], i)
            param_idx += 2
        return qc

    def cost_fn(params):
        qc = ansatz(params)
        state = Statevector(qc)
        return float(np.real(state.expectation_value(H)))

    best_energy = float('inf')
    for _ in range(10):
        x0 = np.random.uniform(0, 2 * np.pi, 32)
        res = minimize(cost_fn, x0, method='L-BFGS-B', options={'maxiter': 1000})
        if res.fun < best_energy:
            best_energy = res.fun

    return float(best_energy)

