import numpy as np
from scipy.linalg import expm
from qiskit import QuantumCircuit
from qiskit.quantum_info import Operator

def solve():
    # Define Pauli matrices
    X = np.array([[0, 1], [1, 0]], dtype=complex)
    Y = np.array([[0, -1j], [1j, 0]], dtype=complex)
    Z = np.array([[1, 0], [0, -1]], dtype=complex)
    I = np.eye(2, dtype=complex)

    # H = 1.1815 * XY - 1.9782 * ZY + 0.8636 * XI + 0.4761 * YZ
    # Qiskit ordering: "XY" -> X on q1, Y on q0 -> np.kron(X, Y)
    H_mat = (
        1.1815 * np.kron(X, Y)
        - 1.9782 * np.kron(Z, Y)
        + 0.8636 * np.kron(X, I)
        + 0.4761 * np.kron(Y, Z)
    )

    t = 0.8
    U_exact = expm(-1j * H_mat * t)

    terms = [
        ("XY", 1.1815),
        ("ZY", -1.9782),
        ("XI", 0.8636),
        ("YZ", 0.4761)
    ]

    def append_pauli_evolution(qc, pauli_str, theta):
        p1 = pauli_str[0]
        p0 = pauli_str[1]

        if p0 == 'I' and p1 != 'I':
            if p1 == 'X':
                qc.rx(2 * theta, 1)
            elif p1 == 'Y':
                qc.ry(2 * theta, 1)
            elif p1 == 'Z':
                qc.rz(2 * theta, 1)
        elif p1 == 'I' and p0 != 'I':
            if p0 == 'X':
                qc.rx(2 * theta, 0)
            elif p0 == 'Y':
                qc.ry(2 * theta, 0)
            elif p0 == 'Z':
                qc.rz(2 * theta, 0)
        elif p0 != 'I' and p1 != 'I':
            if p0 == 'X':
                qc.h(0)
            elif p0 == 'Y':
                qc.rx(np.pi / 2, 0)
            if p1 == 'X':
                qc.h(1)
            elif p1 == 'Y':
                qc.rx(np.pi / 2, 1)

            qc.cx(0, 1)
            qc.rz(2 * theta, 1)
            qc.cx(0, 1)

            if p0 == 'X':
                qc.h(0)
            elif p0 == 'Y':
                qc.rx(-np.pi / 2, 0)
            if p1 == 'X':
                qc.h(1)
            elif p1 == 'Y':
                qc.rx(-np.pi / 2, 1)

    # Try 1st order Trotter
    for N in range(1, 30):
        qc = QuantumCircuit(2)
        dt = t / N
        for _ in range(N):
            for pauli, coeff in terms:
                append_pauli_evolution(qc, pauli, coeff * dt)

        U_circuit = Operator(qc).data
        fid = np.abs(np.trace(U_exact.conj().T @ U_circuit)) / 4
        if fid > 0.995:
            return qc

    # Try 2nd order Trotter if 1st order didn't suffice
    for N in range(1, 30):
        qc = QuantumCircuit(2)
        dt = t / N
        for _ in range(N):
            for pauli, coeff in terms:
                append_pauli_evolution(qc, pauli, coeff * dt / 2)
            for pauli, coeff in reversed(terms):
                append_pauli_evolution(qc, pauli, coeff * dt / 2)

        U_circuit = Operator(qc).data
        fid = np.abs(np.trace(U_exact.conj().T @ U_circuit)) / 4
        if fid > 0.995:
            return qc

    return qc

import numpy as np
from qiskit import QuantumCircuit

def solve():
    # Hamiltonian terms: (Pauli string, coefficient)
    # Qiskit convention: rightmost character is qubit 0, leftmost is qubit 2.
    terms = [
        ("ZXZ", 0.2257),
        ("ZYX", 0.1715),
        ("IYZ", 1.7214),
        ("ZYZ", -0.8902),
        ("XIX", 1.4067)
    ]

    t = 1.0
    r = 15  # Number of Trotter steps

    qc = QuantumCircuit(3)

    def add_pauli_evolution(circuit, pauli_str, theta):
        active_qubits = []
        for i in range(3):
            p = pauli_str[2 - i]
            if p != 'I':
                active_qubits.append((i, p))

        if not active_qubits:
            return

        # 1. Basis change to Z
        for q, p in active_qubits:
            if p == 'X':
                circuit.h(q)
            elif p == 'Y':
                circuit.rx(-np.pi/2, q)

        # 2. CNOT cascade
        for i in range(len(active_qubits) - 1):
            circuit.cx(active_qubits[i][0], active_qubits[i+1][0])

        # 3. Rz rotation
        last_q = active_qubits[-1][0]
        circuit.rz(2 * theta, last_q)

        # 4. Inverse CNOT cascade
        for i in range(len(active_qubits) - 2, -1, -1):
            circuit.cx(active_qubits[i][0], active_qubits[i+1][0])

        # 5. Inverse basis change
        for q, p in active_qubits:
            if p == 'X':
                circuit.h(q)
            elif p == 'Y':
                circuit.rx(np.pi/2, q)

    # Second-order Trotter-Suzuki expansion
    for _ in range(r):
        # Forward half-steps
        for pauli_str, coeff in terms:
            theta = coeff * t / (2 * r)
            add_pauli_evolution(qc, pauli_str, theta)
        # Backward half-steps
        for pauli_str, coeff in reversed(terms):
            theta = coeff * t / (2 * r)
            add_pauli_evolution(qc, pauli_str, theta)

    return qc

