    Y_mat = np.array([[0, -1j], [1j, 0]], dtype=complex)
    Z_mat = np.array([[1, 0], [0, -1]], dtype=complex)

    pauli_dict = {'I': I_mat, 'X': X_mat, 'Y': Y_mat, 'Z': Z_mat}

    def get_pauli_matrix(pauli_str):
        mat = pauli_dict[pauli_str[0]]
        for char in pauli_str[1:]:
            mat = np.kron(mat, pauli_dict[char])
        return mat

    H_mat = np.zeros((8, 8), dtype=complex)
    for pauli, coeff in zip(paulis, coeffs):
        H_mat += coeff * get_pauli_matrix(pauli)

    U_exact = scipy.linalg.expm(-1j * H_mat * t)

    def append_pauli_evolution(qc, pauli_str, theta):
        reversed_str = pauli_str[::-1]
        active_qubits = [i for i, char in enumerate(reversed_str) if char != 'I']

        if not active_qubits:
            return

        for q in active_qubits:
            char = reversed_str[q]
            if char == 'X':
                qc.h(q)
            elif char == 'Y':
                qc.rx(np.pi / 2, q)

        for i in range(len(active_qubits) - 1):
            qc.cx(active_qubits[i], active_qubits[i+1])

        qc.rz(2 * theta, active_qubits[-1])

        for i in range(len(active_qubits) - 2, -1, -1):
            qc.cx(active_qubits[i], active_qubits[i+1])

        for q in active_qubits:
            char = reversed_str[q]
            if char == 'X':
                qc.h(q)
            elif char == 'Y':
                qc.rx(-np.pi / 2, q)

    def get_trotter_circuit_order1(r):
        qc = QuantumCircuit(3)
        dt = t / r
        for _ in range(r):
            for pauli, coeff in zip(paulis, coeffs):
                append_pauli_evolution(qc, pauli, coeff * dt)
        return qc

    def get_trotter_circuit_order2(r):
        qc = QuantumCircuit(3)
        dt = t / r
        m = len(paulis)
        for _ in range(r):
            for i in range(m - 1):
                append_pauli_evolution(qc, paulis[i], coeffs[i] * dt / 2)
            append_pauli_evolution(qc, paulis[-1], coeffs[-1] * dt)
            for i in range(m - 2, -1, -1):
                append_pauli_evolution(qc, paulis[i], coeffs[i] * dt / 2)
        return qc

    for r in range(1, 15):
        qc = get_trotter_circuit_order2(r)
        U_circuit = Operator(qc).data
        fidelity = np.abs(np.trace(U_exact.conj().T @ U_circuit)) / 8
        if fidelity > 0.995:
