    for r in range(1, 25):
        qc = get_trotter_circuit_order1(r)
        U_circuit = Operator(qc).data
        fidelity = np.abs(np.trace(U_exact.conj().T @ U_circuit)) / 8
        if fidelity > 0.995:
            return qc

    return get_trotter_circuit_order2(5)

