        ("XXYI", 1.9515),
        ("XZZX", 0.0571)
    ]
    t = 1.0

    H_op = SparsePauliOp.from_list(terms)
    H_mat = H_op.to_matrix()
    U_exact = scipy.linalg.expm(-1j * H_mat * t)

    def add_pauli_evolution(qc, pauli_str, theta):
        n = len(pauli_str)
        active_qubits = []
        for i in range(n):
            qubit_idx = n - 1 - i
            char = pauli_str[i]
            if char != 'I':
                active_qubits.append((qubit_idx, char))

        active_qubits.sort(key=lambda x: x[0])
        if not active_qubits:
            return

        for q, char in active_qubits:
            if char == 'X':
                qc.h(q)
            elif char == 'Y':
                qc.rx(np.pi / 2, q)

        for i in range(len(active_qubits) - 1):
            qc.cx(active_qubits[i][0], active_qubits[i+1][0])

        target_q = active_qubits[-1][0]
        qc.rz(2 * theta, target_q)

        for i in range(len(active_qubits) - 2, -1, -1):
            qc.cx(active_qubits[i][0], active_qubits[i+1][0])

        for q, char in active_qubits:
            if char == 'X':
                qc.h(q)
            elif char == 'Y':
                qc.rx(-np.pi / 2, q)

    best_qc = None
    for r in range(1, 100):
        qc = QuantumCircuit(4)
        for _ in range(r):
            for pauli_str, coeff in terms:
                theta = coeff * t / r
                add_pauli_evolution(qc, pauli_str, theta)

        U_trotter = Operator(qc).data
        fidelity = np.abs(np.trace(U_exact.conj().T @ U_trotter)) / 16.0
        if fidelity > 0.995:
            best_qc = qc
            break

    for r_2 in range(1, r):
        qc_2 = QuantumCircuit(4)
        for _ in range(r_2):
            for pauli_str, coeff in terms:
                theta = coeff * t / (2 * r_2)
                add_pauli_evolution(qc_2, pauli_str, theta)
            for pauli_str, coeff in reversed(terms):
