        U_trotter_2 = Operator(qc_2).data
        fidelity_2 = np.abs(np.trace(U_exact.conj().T @ U_trotter_2)) / 16.0
        if fidelity_2 > 0.995:
            if r_2 * 2 < r:
                best_qc = qc_2
