import itertools
from collections import deque
from qiskit import QuantumCircuit

def solve():
    # 1. Generate terms of size <= 3
    terms = []
    for p in itertools.product([0, 1, 2], repeat=4):
        size = sum(1 for x in p if x != 0)
        if size <= 3:
            terms.append(p)

    # 2. Compute vectors
    term_vectors = []
    for t in terms:
        vec = 0
        for x in range(16):
            match = True
            for i in range(4):
                bit = (x >> i) & 1
                if t[i] == 1 and bit == 0:
                    match = False
                    break
                elif t[i] == 2 and bit == 1:
                    match = False
                    break
            if match:
                vec |= (1 << x)
        term_vectors.append((t, vec))

    # 3. Target vector
    f_vals = [0, 1, 1, 1, 1, 0, 1, 0, 1, 0, 0, 1, 1, 1, 0, 0]
    target_vec = 0
    for i, val in enumerate(f_vals):
        if val:
            target_vec |= (1 << i)

    # 4. BFS to find the shortest ESOP
    dist = {0: []}
    queue = deque([0])
    chosen_indices = []
    while queue:
        curr = queue.popleft()
        if curr == target_vec:
            chosen_indices = dist[curr]
            break
        for i, (term, vec) in enumerate(term_vectors):
            nxt = curr ^ vec
            if nxt not in dist:
                dist[nxt] = dist[curr] + [i]
                queue.append(nxt)

    chosen_terms = [term_vectors[i][0] for i in chosen_indices]

    # 5. Build the QuantumCircuit
    # Qubits: 0, 1, 2, 3 (inputs), 4 (ancilla), 5 (target)
    qc = QuantumCircuit(6)

    for t in chosen_terms:
        # Identify active controls and their polarities
        controls = []
        for i in range(4):
            if t[i] != 0:
                controls.append((i, t[i])) # (qubit_index, polarity)

        # Apply X gates for negative controls
        for idx, pol in controls:
            if pol == 2:
                qc.x(idx)

        # Apply the multi-controlled gate to target (qubit 5) using ancilla (qubit 4)
        num_controls = len(controls)
        if num_controls == 0:
            qc.x(5)
        elif num_controls == 1:
            qc.cx(controls[0][0], 5)
        elif num_controls == 2:
            qc.ccx(controls[0][0], controls[1][0], 5)
        elif num_controls == 3:
            # Use ancilla 4
            qc.ccx(controls[0][0], controls[1][0], 4)
            qc.ccx(4, controls[2][0], 5)
            qc.ccx(controls[0][0], controls[1][0], 4) # uncompute

        # Restore negative controls
        for idx, pol in controls:
            if pol == 2:
                qc.x(idx)

    return qc

import numpy as np

def solve():
    I = np.eye(2, dtype=complex)
    X = np.array([[0, 1], [1, 0]], dtype=complex)
    Y = np.array([[0, -1j], [1j, 0]], dtype=complex)
    Z = np.array([[1, 0], [0, -1]], dtype=complex)

    paulis = [I, X, Y, Z]

    def embed_1q(op, k):
        res = np.eye(1, dtype=complex)
        for i in range(2, -1, -1):
            if i == k:
                res = np.kron(res, op)
            else:
                res = np.kron(res, I)
        return res

    def embed_2q(op1, op2, q1, q2):
        res = np.eye(1, dtype=complex)
        for i in range(2, -1, -1):
            if i == q1:
                res = np.kron(res, op1)
            elif i == q2:
                res = np.kron(res, op2)
            else:
                res = np.kron(res, I)
        return res

    def apply_1q_noise(rho, k, p=0.005):
        X_k = embed_1q(X, k)
        Y_k = embed_1q(Y, k)
        Z_k = embed_1q(Z, k)
        sum_term = X_k @ rho @ X_k + Y_k @ rho @ Y_k + Z_k @ rho @ Z_k
        return (1 - p) * rho + (p / 3.0) * sum_term

    def apply_2q_noise(rho, q1, q2, p=0.02):
        sum_term = np.zeros_like(rho)
        for i in range(4):
            for j in range(4):
                if i == 0 and j == 0:
                    continue
                P = embed_2q(paulis[i], paulis[j], q1, q2)
                sum_term += P @ rho @ P.conj().T
        return (1 - p) * rho + (p / 15.0) * sum_term

    def get_cx(control, target):
        M = np.zeros((8, 8), dtype=complex)
        for x in range(8):
            b = [(x >> i) & 1 for i in range(3)]
            if b[control] == 1:
                b[target] = 1 - b[target]
            y = sum(b[i] << i for i in range(3))
            M[y, x] = 1
        return M

    def ry(theta):
        return np.array([
            [np.cos(theta/2), -np.sin(theta/2)],
