                         [-1j*np.sin(theta/2), np.cos(theta/2)]], dtype=complex)

    def get_1q_gate(U, k):
        ops = [I] * 4
        ops[3 - k] = U
        res = ops[0]
        for op in ops[1:]:
            res = np.kron(res, op)
        return res

    def get_cx(c, t):
        ops0 = [I] * 4
        ops0[3 - c] = P0
        ops0[3 - t] = I
        res0 = ops0[0]
        for op in ops0[1:]:
            res0 = np.kron(res0, op)

