        ops1[3 - c] = P1
        ops1[3 - t] = X
        res1 = ops1[0]
        for op in ops1[1:]:
            res1 = np.kron(res1, op)

        return res0 + res1

    def get_2q_op(A, B, c, t):
        ops = [I] * 4
        ops[3 - c] = A
        ops[3 - t] = B
        res = ops[0]
        for op in ops[1:]:
