            rho = (1 - p) * rho + (p / 15) * sum_noise

    fidelity = np.real(psi.conj() @ rho @ psi)
    return float(fidelity)

import numpy as np

def solve():
    I = np.eye(2, dtype=complex)
    X = np.array([[0, 1], [1, 0]], dtype=complex)
    Y = np.array([[0, -1j], [1j, 0]], dtype=complex)
    Z = np.array([[1, 0], [0, -1]], dtype=complex)
    H = np.array([[1, 1], [1, -1]], dtype=complex) / np.sqrt(2)
    S = np.array([[1, 0], [0, 1j]], dtype=complex)

    def rx(theta):
        return np.array([[np.cos(theta/2), -1j*np.sin(theta/2)],
                         [-1j*np.sin(theta/2), np.cos(theta/2)]], dtype=complex)

    def ry(theta):
        return np.array([[np.cos(theta/2), -np.sin(theta/2)],
                         [np.sin(theta/2), np.cos(theta/2)]], dtype=complex)

    def make_op1(op, k):
        ops = [I] * 5
        ops[4 - k] = op
        res = ops[0]
        for o in ops[1:]:
            res = np.kron(res, o)
        return res

    def make_cx(c, t):
        P0 = np.array([[1, 0], [0, 0]], dtype=complex)
        P1 = np.array([[0, 0], [0, 1]], dtype=complex)

        ops_P0 = [I] * 5
        ops_P0[4 - c] = P0
        term1 = ops_P0[0]
        for o in ops_P0[1:]:
            term1 = np.kron(term1, o)

        ops_P1_X = [I] * 5
        ops_P1_X[4 - c] = P1
        ops_P1_X[4 - t] = X
        term2 = ops_P1_X[0]
        for o in ops_P1_X[1:]:
            term2 = np.kron(term2, o)

        return term1 + term2

    def apply_noise_1(rho, k, p=0.002):
        X_k = make_op1(X, k)
        Y_k = make_op1(Y, k)
        Z_k = make_op1(Z, k)
        return (1 - p) * rho + (p / 3) * (X_k @ rho @ X_k + Y_k @ rho @ Y_k + Z_k @ rho @ Z_k)

    def apply_noise_2(rho, c, t, p=0.01):
        sum_term = np.zeros_like(rho)
        paulis = [I, X, Y, Z]
        for i in range(4):
            for j in range(4):
                if i == 0 and j == 0:
                    continue
                a = paulis[i]
                b = paulis[j]
                ops = [I] * 5
                ops[4 - c] = a
                ops[4 - t] = b
                op = ops[0]
                for o in ops[1:]:
                    op = np.kron(op, o)
                sum_term += op @ rho @ op
        return (1 - p) * rho + (p / 15) * sum_term

    gates = [
        ('cx', [4, 3]),
        ('ry', 3.565913, [1]),
        ('rx', 2.425831, [4]),
        ('cx', [2, 4]),
        ('s', [4]),
        ('cx', [1, 4]),
        ('cx', [3, 0]),
        ('y', [4]),
        ('h', [2]),
        ('x', [3]),
        ('x', [2]),
        ('s', [3]),
        ('cx', [1, 2]),
        ('cx', [3, 1]),
        ('y', [1]),
        ('z', [0]),
        ('s', [0]),
        ('ry', 2.901252, [3]),
        ('cx', [3, 2]),
        ('rx', 1.899734, [0])
    ]

    def get_gate_op(gate):
        gtype = gate[0]
        if gtype == 'cx':
            c, t = gate[1]
            return make_cx(c, t)
        elif gtype == 'ry':
            theta = gate[1]
            k = gate[2][0]
            return make_op1(ry(theta), k)
        elif gtype == 'rx':
            theta = gate[1]
            k = gate[2][0]
            return make_op1(rx(theta), k)
        elif gtype == 's':
            k = gate[1][0]
            return make_op1(S, k)
        elif gtype == 'y':
            k = gate[1][0]
            return make_op1(Y, k)
        elif gtype == 'h':
            k = gate[1][0]
            return make_op1(H, k)
        elif gtype == 'x':
            k = gate[1][0]
            return make_op1(X, k)
        elif gtype == 'z':
            k = gate[1][0]
            return make_op1(Z, k)
        else:
            raise ValueError(f"Unknown gate {gtype}")

    psi = np.zeros(32, dtype=complex)
    psi[0] = 1.0

    rho = np.zeros((32, 32), dtype=complex)
    rho[0, 0] = 1.0

    for gate in gates:
        U = get_gate_op(gate)
        psi = U @ psi
        rho = U @ rho @ U.conj().T

        gtype = gate[0]
        if gtype == 'cx':
            c, t = gate[1]
            rho = apply_noise_2(rho, c, t, p=0.01)
        elif gtype in ['ry', 'rx']:
            k = gate[2][0]
            rho = apply_noise_1(rho, k, p=0.002)
        else:
            k = gate[1][0]
            rho = apply_noise_1(rho, k, p=0.002)

    fidelity = np.vdot(psi, rho @ psi)
    return float(np.real(fidelity))

