import numpy as np

def solve():
    gates = [
        ('z', [0], None),
        ('cx', [0, 3], None),
        ('t', [1], None),
        ('s', [4], None),
        ('cx', [4, 2], None),
        ('x', [0], None),
        ('rx', [3], 2.532508),
        ('rx', [1], 2.122953),
        ('s', [4], None),
        ('t', [3], None),
        ('x', [1], None),
        ('cx', [2, 0], None),
        ('t', [3], None),
        ('rz', [1], 4.134292),
        ('ry', [1], 4.808796),
        ('cx', [4, 2], None),
        ('rx', [3], 5.057470),
        ('cx', [1, 0], None),
        ('rz', [0], 0.887469),
        ('t', [1], None),
        ('cx', [1, 3], None),
        ('x', [0], None),
        ('h', [4], None),
        ('h', [4], None),
        ('rx', [4], 1.479008),
        ('cx', [4, 3], None),
        ('cx', [1, 2], None),
        ('cx', [2, 3], None),
        ('cx', [3, 2], None),
        ('y', [0], None)
    ]

    def get_gate_matrix(name, params=None):
        if name == 'h':
            return np.array([[1, 1], [1, -1]]) / np.sqrt(2)
        elif name == 'x':
            return np.array([[0, 1], [1, 0]])
        elif name == 'y':
            return np.array([[0, -1j], [1j, 0]])
        elif name == 'z':
            return np.array([[1, 0], [0, -1]])
        elif name == 's':
            return np.array([[1, 0], [0, 1j]])
        elif name == 't':
            return np.array([[1, 0], [0, np.exp(1j * np.pi / 4)]])
        elif name == 'rx':
            theta = params
            return np.array([[np.cos(theta/2), -1j*np.sin(theta/2)],
                             [-1j*np.sin(theta/2), np.cos(theta/2)]])
        elif name == 'ry':
            theta = params
            return np.array([[np.cos(theta/2), -np.sin(theta/2)],
                             [np.sin(theta/2), np.cos(theta/2)]])
        elif name == 'rz':
            theta = params
            return np.array([[np.exp(-1j*theta/2), 0],
                             [0, np.exp(1j*theta/2)]])
        else:
            raise ValueError(f"Unknown gate {name}")

    def get_1q_op(U, k):
        op = np.eye(1)
        for i in range(4, -1, -1):
            if i == k:
                op = np.kron(op, U)
            else:
                op = np.kron(op, np.eye(2))
        return op

    def get_cx_op(c, t):
        P0 = np.array([[1, 0], [0, 0]])
        P1 = np.array([[0, 0], [0, 1]])
        X = np.array([[0, 1], [1, 0]])
        I = np.eye(2)

        op1 = np.eye(1)
        op2 = np.eye(1)
        for i in range(4, -1, -1):
            if i == c:
                op1 = np.kron(op1, P0)
            else:
                op1 = np.kron(op1, I)

            if i == c:
                op2 = np.kron(op2, P1)
            elif i == t:
                op2 = np.kron(op2, X)
            else:
                op2 = np.kron(op2, I)

        return op1 + op2

    def apply_1q_noise(rho, q, p=0.001):
        X = np.array([[0, 1], [1, 0]])
        Y = np.array([[0, -1j], [1j, 0]])
        Z = np.array([[1, 0], [0, -1]])

        X_op = get_1q_op(X, q)
        Y_op = get_1q_op(Y, q)
        Z_op = get_1q_op(Z, q)

        noisy_sum = (X_op @ rho @ X_op + 
                     Y_op @ rho @ Y_op + 
                     Z_op @ rho @ Z_op)
        return (1 - p) * rho + (p / 3.0) * noisy_sum

    def apply_2q_noise(rho, q1, q2, p=0.008):
        Paulis = [np.eye(2), 
                  np.array([[0, 1], [1, 0]]), 
                  np.array([[0, -1j], [1j, 0]]), 
                  np.array([[1, 0], [0, -1]])]

        noisy_sum = np.zeros_like(rho)
        for i in range(4):
            for j in range(4):
                if i == 0 and j == 0:
                    continue
                op = np.eye(1)
                for qubit in range(4, -1, -1):
                    if qubit == q1:
                        op = np.kron(op, Paulis[i])
                    elif qubit == q2:
                        op = np.kron(op, Paulis[j])
                    else:
                        op = np.kron(op, np.eye(2))
                noisy_sum += op @ rho @ op.conj().T

        return (1 - p) * rho + (p / 15.0) * noisy_sum

    # Ideal state propagation
    psi = np.zeros(32, dtype=complex)
    psi[0] = 1.0

    for name, qubits, param in gates:
        if name == 'cx':
            c, t = qubits
            op = get_cx_op(c, t)
        else:
            q = qubits[0]
            U = get_gate_matrix(name, param)
            op = get_1q_op(U, q)
        psi = op @ psi

    # Noisy state propagation
    rho = np.zeros((32, 32), dtype=complex)
    rho[0, 0] = 1.0

    for name, qubits, param in gates:
        if name == 'cx':
            c, t = qubits
            op = get_cx_op(c, t)
            rho = op @ rho @ op.conj().T
            rho = apply_2q_noise(rho, c, t, p=0.008)
        else:
            q = qubits[0]
            U = get_gate_matrix(name, param)
            op = get_1q_op(U, q)
            rho = op @ rho @ op.conj().T
            rho = apply_1q_noise(rho, q, p=0.001)

    fidelity = np.real(psi.conj() @ rho @ psi)
    return float(fidelity)

