                    physical_to_logical[a] = logical_b
                    physical_to_logical[b] = logical_a

                # Apply CNOT
                routed_circuit.cx(path[-2], path[-1])

                # Move control back
                for i in range(len(path) - 2, 0, -1):
                    swap_qubits = (path[i], path[i-1])
                    routed_circuit.swap(*swap_qubits)
