import numpy as np

def solve():
    # Define Pauli matrices
    I = np.eye(2, dtype=complex)
    X = np.array([[0, 1], [1, 0]], dtype=complex)
    Y = np.array([[0, -1j], [1j, 0]], dtype=complex)
    Z = np.array([[1, 0], [0, -1]], dtype=complex)

    # Define gate matrices
    def ry(theta):
        return np.array([
            [np.cos(theta/2), -np.sin(theta/2)],
            [np.sin(theta/2), np.cos(theta/2)]
        ], dtype=complex)

    def s_gate():
        return np.array([[1, 0], [0, 1j]], dtype=complex)

    def t_gate():
        return np.array([[1, 0], [0, np.exp(1j * np.pi / 4)]], dtype=complex)

    # Initial state |000><000|
    rho = np.zeros((8, 8), dtype=complex)
    rho[0, 0] = 1.0

    # Circuit gates in order
    gates = [
        (ry(4.374501), [2]),
        (s_gate(), [0]),
        (Y, [2]),
        (ry(3.504125), [1]),
        (s_gate(), [1]),
        (t_gate(), [0]),
        (X, [1]),
        (Y, [1])
    ]

    # Depolarizing noise parameters
    p1 = 0.005
    p2 = 0.02

    # Helper function to apply single-qubit gate with noise
    def apply_single_qubit_gate(rho, gate, qubit):
        n = int(np.log2(rho.shape[0]))
        full_gate = 1
        for q in range(n):
            if q == qubit:
                full_gate = np.kron(full_gate, gate)
            else:
                full_gate = np.kron(full_gate, I)

        # Apply gate
        rho = full_gate @ rho @ full_gate.conj().T

        # Apply depolarizing noise
        noise_ops = [X, Y, Z]
        for op in noise_ops:
            full_op = 1
            for q in range(n):
                if q == qubit:
                    full_op = np.kron(full_op, op)
                else:
                    full_op = np.kron(full_op, I)
            rho = (1 - p1) * rho + (p1 / 3) * (full_op @ rho @ full_op.conj().T)

        return rho

    # Apply all gates
    for gate, qubits in gates:
        if len(qubits) == 1:
            rho = apply_single_qubit_gate(rho, gate, qubits[0])
        else:
            # No 2-qubit gates in this circuit, but included for completeness
            pass

    # Compute ideal state (no noise)
    ideal_rho = np.zeros((8, 8), dtype=complex)
    ideal_rho[0, 0] = 1.0

    for gate, qubits in gates:
        n = int(np.log2(ideal_rho.shape[0]))
        full_gate = 1
        for q in range(n):
            if q == qubits[0]:
                full_gate = np.kron(full_gate, gate)
            else:
                full_gate = np.kron(full_gate, I)
        ideal_rho = full_gate @ ideal_rho @ full_gate.conj().T

    # Compute fidelity
    fidelity = np.real(np.trace(ideal_rho @ rho))

    return float(fidelity)
