import numpy as np

def solve():
    # Gate definitions
    I = np.eye(2, dtype=complex)
    X = np.array([[0, 1], [1, 0]], dtype=complex)
    Y = np.array([[0, -1j], [1j, 0]], dtype=complex)
    Z = np.array([[1, 0], [0, -1]], dtype=complex)
    H = np.array([[1, 1], [1, -1]], dtype=complex) / np.sqrt(2)
    S = np.array([[1, 0], [0, 1j]], dtype=complex)
    T = np.array([[1, 0], [0, np.exp(1j * np.pi / 4)]], dtype=complex)

    def RX(theta):
        return np.array([
            [np.cos(theta/2), -1j*np.sin(theta/2)],
            [-1j*np.sin(theta/2), np.cos(theta/2)]
        ], dtype=complex)

    def RY(theta):
        return np.array([
            [np.cos(theta/2), -np.sin(theta/2)],
            [np.sin(theta/2), np.cos(theta/2)]
        ], dtype=complex)

    def RZ(theta):
        return np.array([
            [np.exp(-1j*theta/2), 0],
            [0, np.exp(1j*theta/2)]
        ], dtype=complex)

    def CX(control, target, n_qubits):
        mat = np.eye(4, dtype=complex)
        mat[2:, 2:] = np.array([[0, 1], [1, 0]], dtype=complex)
        return expand_operator(mat, [control, target], n_qubits)

    def expand_operator(op, qubits, n_qubits):
        full_op = np.eye(1, dtype=complex)
        for q in range(n_qubits):
            if q in qubits:
                idx = qubits.index(q)
                full_op = np.kron(op if idx == 0 else op.T, full_op)
            else:
                full_op = np.kron(I, full_op)
        return full_op

    def depolarizing_channel_1q(rho, p):
        return (1 - p) * rho + (p / 3) * (np.dot(X, np.dot(rho, X)) +
                                         np.dot(Y, np.dot(rho, Y)) +
                                         np.dot(Z, np.dot(rho, Z)))

    def depolarizing_channel_2q(rho, p):
