            np.kron(I, X), np.kron(I, Y), np.kron(I, Z),
            np.kron(X, I), np.kron(X, X), np.kron(X, Y), np.kron(X, Z),
            np.kron(Y, I), np.kron(Y, X), np.kron(Y, Y), np.kron(Y, Z),
            np.kron(Z, I), np.kron(Z, X), np.kron(Z, Y), np.kron(Z, Z)
        ]
        return (1 - p) * rho + (p / 15) * sum(np.dot(P, np.dot(rho, P)) for P in paulis)

    # Initialize state
    n_qubits = 4
    rho = np.zeros((2**n_qubits, 2**n_qubits), dtype=complex)
