        return apply_single_qubit_gate(mat, q, n_qubits)

    def z(q):
        mat = np.array([[1, 0], [0, -1]], dtype=complex)
        return apply_single_qubit_gate(mat, q, n_qubits)

    def s(q):
        mat = np.array([[1, 0], [0, 1j]], dtype=complex)
        return apply_single_qubit_gate(mat, q, n_qubits)

    def t(q):
        mat = np.array([[1, 0], [0, np.exp(1j * np.pi / 4)]], dtype=complex)
        return apply_single_qubit_gate(mat, q, n_qubits)

    def ry(theta, q):
        mat = np.array([
            [np.cos(theta / 2), -np.sin(theta / 2)],
            [np.sin(theta / 2), np.cos(theta / 2)]
        ], dtype=complex)
        return apply_single_qubit_gate(mat, q, n_qubits)

    def rz(theta, q):
        mat = np.array([
            [np.exp(-1j * theta / 2), 0],
            [0, np.exp(1j * theta / 2)]
        ], dtype=complex)
        return apply_single_qubit_gate(mat, q, n_qubits)

    def cx(control, target):
        mat = np.eye(4, dtype=complex)
        mat[2:, 2:] = np.array([[0, 1], [1, 0]], dtype=complex)
        return apply_two_qubit_gate(mat, control, target, n_qubits)

    def apply_single_qubit_gate(mat, q, n):
        full_mat = 1
        for i in range(n):
            if i == q:
                full_mat = np.kron(full_mat, mat)
            else:
                full_mat = np.kron(full_mat, np.eye(2, dtype=complex))
        return full_mat

    def apply_two_qubit_gate(mat, control, target, n):
        if control == target:
            raise ValueError("Control and target qubits must be different")
