    circuit_b = qiskit.qasm2.loads(qasm_b)

    op_a = Operator(circuit_a)
    op_b = Operator(circuit_b)

    # Check if unitaries are equivalent up to global phase
    # U1 = e^(iθ) * U2 means U1 * U2† should be a scalar multiple of identity
    product = op_a @ op_b.adjoint()
