    # Check if product is a scalar multiple of identity
    n = product_data.shape[0]
    identity = np.eye(n, dtype=complex)

    # Find the scalar factor (should be constant for all diagonal elements if equivalent)
    if np.abs(product_data[0, 0]) > 1e-10:
        scalar = product_data[0, 0]
        normalized = product_data / scalar
        if np.allclose(normalized, identity, atol=1e-10):
