from qiskit.quantum_info import Operator, Pauli
import numpy as np

def solve():
    # Hamiltonian coefficients and Pauli strings
    coeffs = [0.8654, 1.2474, 0.5024, 0.5194, 1.9143]
    paulis = ['IIY', 'ZYX', 'YZX', 'YYZ', 'IXI']
    t = 1.0

    # Number of Trotter steps for good fidelity
    n_trotter = 20
    dt = t / n_trotter

    # Create circuit
    qc = QuantumCircuit(3)

    def add_pauli_rotation(qc, pauli_string, angle):
        """Add e^{-i*angle*P} where P is a Pauli string"""
        # Convert to appropriate basis
        for i, p in enumerate(pauli_string):
            if p == 'X':
                qc.h(i)
            elif p == 'Y':
                qc.rx(-np.pi/2, i)

        # Add CNOTs to create parity
        active_qubits = [i for i, p in enumerate(pauli_string) if p != 'I']
        if len(active_qubits) > 1:
            for i in range(len(active_qubits)-1):
                qc.cx(active_qubits[i], active_qubits[i+1])

        # Add rotation
        if len(active_qubits) > 0:
            qc.rz(2*angle, active_qubits[-1])

        # Undo CNOTs
        if len(active_qubits) > 1:
            for i in range(len(active_qubits)-2, -1, -1):
                qc.cx(active_qubits[i], active_qubits[i+1])

        # Convert back from basis
        for i, p in enumerate(pauli_string):
            if p == 'X':
                qc.h(i)
            elif p == 'Y':
                qc.rx(np.pi/2, i)

    # Apply Trotter formula
    for _ in range(n_trotter):
        for coeff, pauli in zip(coeffs, paulis):
            add_pauli_rotation(qc, pauli, -coeff * dt)

    return qc
