        0.9718, 0.1145, 1.7862, -0.4821, -1.3238,
        -1.8761, 1.9121, 0.6688, 0.4858, 1.1280,
        0.6082, -1.7962
    ]

    t = 1.5
    n_trotter_steps = 8  # Increase Trotter steps for better fidelity
    dt = t / n_trotter_steps

    # Create quantum circuit
    qc = QuantumCircuit(5)

    def pauli_evolution(qc, pauli_string, angle):
        """Implement e^{-i*angle*P} where P is a Pauli string"""
        # Count non-identity Paulis
        non_identity = [(i, p) for i, p in enumerate(pauli_string) if p != 'I']

        if len(non_identity) == 0:
            # Global phase, can skip
            return

        # Transform to computational basis
        for i, p in non_identity:
            if p == 'X':
                qc.h(i)
            elif p == 'Y':
                qc.rx(np.pi/2, i)

        # Apply CNOTs to compute parity
        if len(non_identity) > 1:
            for i in range(len(non_identity) - 1):
                qc.cx(non_identity[i][0], non_identity[i+1][0])

        # Apply Rz rotation
        if len(non_identity) > 0:
            qc.rz(2 * angle, non_identity[-1][0])

        # Uncompute CNOTs
        if len(non_identity) > 1:
            for i in range(len(non_identity) - 2, -1, -1):
                qc.cx(non_identity[i][0], non_identity[i+1][0])

        # Transform back from computational basis
        for i, p in non_identity:
            if p == 'X':
                qc.h(i)
            elif p == 'Y':
                qc.rx(-np.pi/2, i)

    # Apply Trotter steps
    for _ in range(n_trotter_steps):
        # Apply each term in the Hamiltonian
        for pauli_str, coeff in zip(pauli_strings, coeffs):
            pauli_evolution(qc, pauli_str, coeff * dt)

