from qiskit import QuantumCircuit, Statevector
from qiskit.quantum_info import Operator
import numpy as np

def solve():
    # Load the circuits from OpenQASM
    circuit_a = QuantumCircuit.from_qasm_str("""
    OPENQASM 2.0;
    include "qelib1.inc";
    qreg q[10];
    s q[0];
    cz q[7],q[5];
    h q[7];
    cx q[3],q[4];
    rz(5.736650091825691) q[6];
    x q[0];
    s q[4];
    s q[0];
    cx q[2],q[4];
    ry(1.0463845822067088) q[8];
    cx q[5],q[2];
    z q[9];
    z q[4];
    y q[7];
    h q[9];
    y q[5];
    y q[5];
    t q[3];
    cx q[1],q[4];
    z q[9];
    z q[3];
    rz(5.56552043588244) q[6];
    rx(0.17981425537182835) q[9];
    t q[6];
    z q[2];
    cz q[3],q[2];
    ry(1.2165291867695998) q[9];
    cz q[8],q[3];
    cx q[6],q[7];
    cx q[4],q[8];
    """)

    circuit_b = QuantumCircuit.from_qasm_str("""
    OPENQASM 2.0;
    include "qelib1.inc";
    qreg q[10];
    s q[0];
    cz q[7],q[5];
    h q[7];
    cx q[3],q[4];
    rz(5.736650091825691) q[6];
    x q[0];
    s q[4];
    s q[0];
    cx q[2],q[4];
    ry(1.0463845822067088) q[8];
    cx q[5],q[2];
    z q[9];
    z q[4];
    y q[7];
    h q[9];
    z q[5];
    y q[5];
    t q[3];
    cx q[1],q[4];
    z q[9];
    z q[3];
    rz(5.56552043588244) q[6];
    rx(0.17981425537182835) q[9];
    t q[6];
    z q[2];
    cz q[3],q[2];
    ry(1.2165291867695998) q[9];
    cz q[8],q[3];
    cx q[6],q[7];
    cx q[4],q[8];
    """)

    # Compute the unitary matrices of the circuits
    unitary_a = Operator(circuit_a).data
    unitary_b = Operator(circuit_b).data

    # Check if the unitary matrices are equivalent up to global phase
    phase = np.exp(1j * np.angle(unitary_a[0, 0]) - 1j * np.angle(unitary_b[0, 0]))
    return np.allclose(unitary_a, unitary_b * phase)

print(solve())
