import numpy as np

def ry(theta):
    return np.array([[np.cos(theta/2), -np.sin(theta/2)], [np.sin(theta/2), np.cos(theta/2)]])

def s():
    return np.array([[1, 0], [0, 1j]])

def y():
    return np.array([[0, -1j], [1j, 0]])

def ry_3qubit(theta, qubit):
    if qubit == 0:
        return np.kron(np.kron(ry(theta), np.eye(2)), np.eye(2))
    elif qubit == 1:
        return np.kron(np.kron(np.eye(2), ry(theta)), np.eye(2))
    elif qubit == 2:
        return np.kron(np.kron(np.eye(2), np.eye(2)), ry(theta))

