from qiskit import QuantumCircuit
from qiskit.quantum_info import Operator, Statevector

def solve():
    # Hamiltonian coefficients
    # H = -0.7012 * YXY - 1.2414 * ZYX - 1.5983 * XXY - 1.9748 * XZX + 1.6701 * YIX
    terms = [
        (-0.7012, 'YXY'),
        (-1.2414, 'ZYX'),
        (-1.5983, 'XXY'),
        (-1.9748, 'XZX'),
        (1.6701, 'YIX')
    ]
    t = 1.0
    steps = 100 # High number of steps to ensure fidelity > 0.99
    dt = t / steps

    qc = QuantumCircuit(3)

    def apply_pauli_string(circuit, pauli_str, coeff, time):
        angle = 2 * coeff * time

        # Change basis to Z
        for i, p in enumerate(pauli_str):
            if p == 'X':
                circuit.h(i)
            elif p == 'Y':
                circuit.rx(np.pi/2, i)

        # Compute parity
        indices = [i for i, p in enumerate(pauli_str) if p != 'I']
        if len(indices) > 1:
            for j in range(len(indices) - 1):
                circuit.cx(indices[j], indices[j+1])

        # Phase rotation
        if len(indices) > 0:
            circuit.rz(angle, indices[-1])

        # Uncompute parity
        if len(indices) > 1:
            for j in range(len(indices) - 2, -1, -1):
                circuit.cx(indices[j], indices[j+1])

        # Restore basis
        for i, p in enumerate(pauli_str):
            if p == 'X':
                circuit.h(i)
            elif p == 'Y':
                circuit.rx(-np.pi/2, i)

    for _ in range(steps):
        for coeff, pauli in terms:
            apply_pauli_string(qc, pauli, coeff, dt)

    return qc

