            full_op = np.kron(full_op, res[i+1] if i+1 < len(res) else np.eye(2))

        # Correcting the loop for Qiskit order:
        # The gate on qubit k is at position (n-1-k) in the tensor product sequence
        # But simpler:
        op = np.eye(1)
        for i in range(total_qubits - 1, -1, -1):
            if i == qubit:
                op = np.kron(op, gate)
            else:
                op = np.kron(op, np.eye(2))
        return op

    def get_cx(ctrl, target, total_qubits):
        op = np.zeros((2**total_qubits, 2**total_qubits), dtype=complex)
        for i in range(2**total_qubits):
            bits = [(i >> j) & 1 for j in range(total_qubits)]
            if bits[ctrl] == 1:
                bits[target] = 1 - bits[target]
            res_i = sum(bits[j] * (2**j) for j in range(total_qubits))
            op[res_i, i] = 1.0
        return op

    def apply_depolarizing_1(rho, qubit, p):
        # D(rho) = (1-p)rho + (p/3)(XrhoX + YrhoY + ZrhoZ)
        # This is equivalent to: rho = (1-p)rho + (p/3) sum(P rho P)
        # For a single qubit, this is rho = (1 - 4p/3)rho + (p/3) Tr_q(rho) * I_q
        # But we can just apply the operators.

        # To avoid full matrix multiplication for every P, we use the property:
        # rho_new = (1-p)*rho + (p/3)*(X rho X + Y rho Y + Z rho Z)
        # where X, Y, Z are the full-space operators.

        # Precompute Pauli matrices for the specific qubit
        paulis = []
        for g in ['x', 'y', 'z']:
            paulis.append(expand_gate(get_single_gate(g), qubit, n_qubits))

        rho_next = (1 - p) * rho
        for P in paulis:
            rho_next += (p / 3.0) * (P @ rho @ P)
        return rho_next

    def apply_depolarizing_2(rho, q1, q2, p):
        # D_2(rho) = (1-p)rho + (p/15) sum_{P != I} P rho P
        # sum_{P != I} P rho P = (sum_{P in {I,X,Y,Z}^2} P rho P) - rho
        # The sum over all 16 Paulis is (1/4^2) * Tr_q1q2(rho) * I_q1q2 * 4^2 = Tr_q1q2(rho) * I_q1q2
        # Wait, the formula for depolarizing channel is:
        # rho = (1-p)rho + (p/15) * (sum_{P} P rho P - rho)

        # Let's just iterate through the 15 Paulis.
        pauli_single = [np.eye(2), get_single_gate('x'), get_single_gate('y'), get_single_gate('z')]
        rho_next = (1 - p) * rho

        for i in range(4):
            for j in range(4):
                if i == 0 and j == 0: continue
                # Construct P = P_i on q1 and P_j on q2
                # This is tricky. Let's build the operator.
                P = np.eye(1)
                for k in range(n_qubits - 1, -1, -1):
                    if k == q1:
                        P = np.kron(P, pauli_single[i])
                    elif k == q2:
                        P = np.kron(P, pauli_single[j])
                    else:
                        P = np.kron(P, np.eye(2))
                rho_next += (p / 15.0) * (P @ rho @ P)
        return rho_next

    gates = [
        ('h', [0], None), ('z', [0], None), ('t', [4], None), ('t', [0], None),
        ('rz', [4], 5.024267), ('ry', [4], 1.798536), ('cx', [4, 0], None), ('h', [0], None),
        ('cx', [1, 2], None), ('cx', [2, 3], None), ('cx', [3, 2], None), ('rx', [4], 3.788735),
        ('ry', [4], 1.851775), ('cx', [0, 3], None), ('x', [2], None), ('cx', [4, 0], None),
        ('cx', [2, 1], None), ('ry', [2], 1.272514), ('z', [1], None), ('cx', [2, 4], None),
        ('ry', [3], 2.176526), ('x', [2], None), ('cx', [4, 1], None), ('y', [1], None),
        ('rx', [0], 2.362067), ('cx', [3, 2], None), ('s', [0], None), ('cx', [3, 4], None),
        ('s', [4], None), ('cx', [4, 2], None)
    ]

    # To calculate fidelity, we need the ideal state
    psi_ideal = np.zeros(dim, dtype=complex)
    psi_ideal[0] = 1.0

    rho_noisy = rho.copy()

    for g_type, qubits, theta in gates:
        if g_type == 'cx':
            U = get_cx(qubits[0], qubits[1], n_qubits)
            # Ideal
            psi_ideal = U @ psi_ideal
            # Noisy
            rho_noisy = U @ rho_noisy @ U.conj().T
            rho_noisy = apply_depolarizing_2(rho_noisy, qubits[0], qubits[1], 0.008)
        else:
            U_single = get_single_gate(g_type, theta)
            U = expand_gate(U_single, qubits[0], n_qubits)
            # Ideal
            psi_ideal = U @ psi_ideal
            # Noisy
            rho_noisy = U @ rho_noisy @ U.conj().T
            rho_noisy = apply_depolarizing_1(rho_noisy, qubits[0], 0.001)

    # Fidelity F = <psi_ideal|rho_noisy|psi_ideal>
    fidelity = np.real(np.vdot(psi_ideal, rho_noisy @ psi_ideal))
    return float(fidelity)

