from qiskit import QuantumCircuit, qasm2
from qiskit.quantum_info import Operator
import numpy as np

def solve():
    qasm_a = """
    OPENQASM 2.0;
    include "qelib1.inc";
    qreg q[4];
    ry(0.15020205251846416) q[2];
    x q[1];
    s q[2];
    t q[3];
    t q[1];
    cx q[0],q[1];
    x q[3];
    s q[1];
    z q[1];
    cx q[1],q[0];
    """

    qasm_b = """
    OPENQASM 2.0;
    include "qelib1.inc";
    qreg q[4];
    ry(0.15020205251846416) q[2];
    x q[1];
    s q[2];
    t q[3];
    t q[1];
    cx q[0],q[1];
    x q[3];
    s q[1];
    z q[1];
    cx q[1],q[0];
    s q[3];
    s q[3];
    z q[3];
    """

    qc_a = qasm2.loads(qasm_a)
    qc_b = qasm2.loads(qasm_b)

    op_a = Operator(qc_a)
    op_b = Operator(qc_b)

    # Check if op_a = exp(i*phi) * op_b
    # This is equivalent to checking if op_a * op_b.adjoint() is a global phase matrix
    # (i.e., a scalar multiple of the identity)
    diff = op_a.compose(op_b.adjoint())
    matrix = diff.data

    # Extract the first non-zero element to determine the potential global phase
    # and check if all other elements match that phase ratio
    nonzero_indices = np.nonzero(matrix)
    if len(nonzero_indices[0]) == 0:
        return False

    first_idx = (nonzero_indices[0][0], nonzero_indices[1][0])
    phase = matrix[first_idx]

    # Normalize the matrix by the phase
    normalized = matrix / phase

    # Check if normalized matrix is identity
    return np.allclose(normalized, np.eye(16))

