from qiskit import QuantumCircuit, qasm2
from qiskit.quantum_info import Operator
import numpy as np

def solve():
    qasm_a = """
    OPENQASM 2.0;
    include "qelib1.inc";
    qreg q[4];
    y q[3];
    cx q[2],q[1];
    ry(1.5391012516365692) q[1];
    ry(1.8903295557165234) q[2];
    s q[0];
    h q[0];
    cz q[2],q[3];
    z q[2];
    x q[3];
    t q[1];
    """

    qasm_b = """
    OPENQASM 2.0;
    include "qelib1.inc";
    qreg q[4];
    t q[3];
    cx q[2],q[1];
    ry(1.5391012516365692) q[1];
    ry(1.8903295557165234) q[2];
    s q[0];
    h q[0];
    cz q[2],q[3];
    z q[2];
    x q[3];
    t q[1];
    """

    qc_a = qasm2.loads(qasm_a)
    qc_b = qasm2.loads(qasm_b)

    op_a = Operator(qc_a)
    op_b = Operator(qc_b)

    # Check if op_a = exp(i*phi) * op_b
    # This is equivalent to checking if op_a * op_b.adjoint() is a global phase
    # (i.e., a scalar matrix)
    diff = op_a.compose(op_b.adjoint())
    matrix = diff.data

    # A matrix is a global phase if it is identity * e^(i*theta)
    # Check if all off-diagonal elements are 0 and diagonal elements are equal
    diag = np.diag(matrix)
    if not np.allclose(matrix - np.diag(diag), 0):
        return False

    return np.allclose(diag / diag[0], 1.0)

